# Anthropic SDK: lazy-loaded on first use so the ~32 MB of SDK modules are not
# imported at startup for users who only use OpenAI models.
_anthropic_sdk = None
_anthropic_sdk_lock = threading.Lock()

def _ensure_anthropic():
    """Import anthropic on first call; cache result. Thread-safe."""
    global _anthropic_sdk
    if _anthropic_sdk is not None:
        return _anthropic_sdk
    with _anthropic_sdk_lock:
        if _anthropic_sdk is None:
            try:
                import anthropic as _ant
                _anthropic_sdk = _ant
            except Exception:
                pass
    return _anthropic_sdk

