# =========================
# SELF-HOSTED ERROR TRACKER
# =========================
# Captures unhandled exceptions to DATA/error_log.json — no third-party signup needed.
# View errors at GET /admin/errors (admin only). Keeps the last 200 entries.
import traceback as _traceback

_ERROR_LOG_LOCK = threading.Lock()
_ERROR_LOG_MAX  = 200

# =========================
# STRUCTURED LOGGING
# =========================
_LOG_LEVELS = {"DEBUG": 10, "INFO": 20, "WARNING": 30, "ERROR": 40, "CRITICAL": 50}
_LOG_MIN_LEVEL = _LOG_LEVELS.get(os.getenv("LOG_LEVEL", "INFO").upper(), 20)

def _log(level: str, msg: str, **ctx) -> None:
    """Structured logger — emits timestamped, levelled lines to stdout.
    Set LOG_LEVEL env var to DEBUG/INFO/WARNING/ERROR to filter output."""
    numeric = _LOG_LEVELS.get(level.upper(), 20)
    if numeric < _LOG_MIN_LEVEL:
        return
    ts = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    extra = (" " + " ".join(f"{k}={v!r}" for k, v in ctx.items())) if ctx else ""
    print(f"[{ts}] [{level.upper()}] {msg}{extra}", flush=True)

def _error_log_path() -> "Path":
    # DATA may not be defined yet at import time — resolve lazily
    try:
        return DATA / "error_log.json"
    except Exception:
        return Path("error_log.json")

def _capture_error(exc: Exception, context: str = "") -> None:
    """Append a structured error entry to the error log. Never raises."""
    try:
        entry = {
            "id":        uuid.uuid4().hex[:12],
            "at":        datetime.utcnow().isoformat() + "Z",
            "context":   context or "",
            "type":      type(exc).__name__,
            "message":   str(exc),
            "traceback": _traceback.format_exc(),
        }
        try:
            entry["path"]   = request.path
            entry["method"] = request.method
        except Exception:
            pass
        # Who hit it — makes errors actionable ("which customer saw this").
        try:
            _u = current_user()
            entry["user"] = (_u.get("username") if isinstance(_u, dict) else None) or ""
        except Exception:
            pass
        # The failing input — sensitive fields redacted so we never log secrets.
        try:
            if request.method in ("POST", "PUT", "PATCH"):
                _raw = request.get_json(silent=True)
                if isinstance(_raw, dict):
                    _SENSITIVE = ("password", "passwd", "pass", "token", "secret",
                                  "openai_key", "claude_key", "api_key", "access_token",
                                  "refresh_token", "card", "cvv", "ssn")
                    def _redact(d):
                        out = {}
                        for k, v in d.items():
                            if any(s in str(k).lower() for s in _SENSITIVE):
                                out[k] = "***redacted***"
                            elif isinstance(v, dict):
                                out[k] = _redact(v)
                            else:
                                out[k] = (v[:500] + "…") if isinstance(v, str) and len(v) > 500 else v
                        return out
                    entry["body"] = _redact(_raw)
                else:
                    entry["body"] = (request.get_data(as_text=True) or "")[:500]
            if request.args:
                entry["args"] = {k: v for k, v in request.args.items()}
        except Exception:
            pass

        path = _error_log_path()
        with _ERROR_LOG_LOCK:
            try:
                log = json.loads(path.read_text(encoding="utf-8")) if path.exists() else []
            except Exception:
                log = []
            log.insert(0, entry)
            log = log[:_ERROR_LOG_MAX]
            tmp = path.with_suffix(".tmp")
            tmp.write_text(json.dumps(log, indent=2), encoding="utf-8")
            tmp.replace(path)
    except Exception:
        pass  # error logger must never crash the app


def _retry_request(method: str, url: str, retries: int = 3, backoff: float = 0.6, **kwargs):
    """HTTP request with exponential backoff on transient errors (429, 5xx, network failures).
    Only use for idempotent/read-only calls — never for sends/creates that would duplicate."""
    import time as _t
    last_exc: Optional[Exception] = None
    for attempt in range(retries):
        try:
            resp = requests.request(method, url, **kwargs)
            if resp.status_code not in (429, 500, 502, 503, 504) or attempt == retries - 1:
                return resp
            _t.sleep(backoff * (2 ** attempt))
        except (requests.ConnectionError, requests.Timeout) as exc:
            last_exc = exc
            if attempt < retries - 1:
                _t.sleep(backoff * (2 ** attempt))
    if last_exc:
        raise last_exc
    return resp  # type: ignore[return-value]


