# =========================
# TRIAL STATUS HELPERS
# =========================

def _get_user_trial_info(username: str) -> Dict[str, Any]:
    """Return trial status for a user.
    Returns dict with: on_trial, trial_end, days_remaining, trial_expired
    """
    default = {"on_trial": False, "trial_end": None, "days_remaining": 0, "trial_expired": False}
    if not username:
        return default
    try:
        seats = (_load_seats().get("seats") or {})
        for seat in seats.values():
            if seat.get("claimed_by") != username:
                continue
            trial_end_str = (seat.get("trial_end") or "").strip()
            if not trial_end_str:
                return default
            try:
                trial_end_dt = datetime.fromisoformat(trial_end_str.replace("Z", ""))
            except Exception:
                return default
            now_dt = datetime.utcnow()
            # Ceiling, not floor: with ~18h left a user should see "1 day", not
            # a confusing "0 days remaining" while the trial is still active.
            import math as _math
            _secs_left = (trial_end_dt - now_dt).total_seconds()
            days_remaining = max(0, _math.ceil(_secs_left / 86400)) if _secs_left > 0 else 0
            trial_expired  = now_dt > trial_end_dt
            on_trial       = bool(seat.get("trial_active")) and not trial_expired
            return {
                "on_trial":       on_trial,
                "trial_end":      trial_end_str,
                "days_remaining": days_remaining,
                "trial_expired":  trial_expired,
            }
    except Exception:
        pass
    return default


def _trial_banner_html(username: str) -> str:
    """Return an HTML banner string for the trial countdown, or empty string."""
    if FREE_TRIAL_DAYS <= 0:
        return ""
    try:
        info = _get_user_trial_info(username)
        if not info.get("on_trial") and not info.get("trial_expired"):
            return ""
        if info.get("trial_expired"):
            return (
                "<div id='trial-banner' style='"
                "background:linear-gradient(135deg,#7f1d1d,#991b1b);"
                "color:#fef2f2;padding:10px 20px;text-align:center;font-size:13px;font-weight:600;"
                "border-bottom:1px solid rgba(255,100,100,.3);'>"
                "⚠️ Your free trial has ended. "
                "<a href='/pricing' style='color:#fca5a5;text-decoration:underline;'>Manage your subscription</a> to keep access."
                "</div>"
            )
        days = info.get("days_remaining", 0)
        day_word = "day" if days == 1 else "days"
        color = "#7c3aed" if days >= 3 else "#b45309"
        return (
            f"<div id='trial-banner' style='"
            f"background:{color};"
            f"color:#f3e8ff;padding:10px 20px;text-align:center;font-size:13px;font-weight:600;"
            f"border-bottom:1px solid rgba(255,255,255,.15);'>"
            f"🎉 Free trial — {days} {day_word} remaining. "
            f"<a href='/pricing' style='color:#e9d5ff;text-decoration:underline;'>Upgrade anytime</a>"
            f"</div>"
        )
    except Exception:
        return ""



GOOGLE_AUTH_URI = "https://accounts.google.com/o/oauth2/v2/auth"
GOOGLE_TOKEN_URI = "https://oauth2.googleapis.com/token"

def _now_epoch() -> int:
    try:
        return int(datetime.utcnow().timestamp())
    except Exception:
        return 0

def _oauth_auth_url(scopes: List[str], redirect_path: str, state: str) -> str:
    redirect_uri = f"{PUBLIC_BASE_URL}{redirect_path}"
    scope_str = " ".join(scopes)
    # Manual URL build (avoid extra deps)
    from urllib.parse import urlencode
    params = {
        "client_id": GOOGLE_CLIENT_ID,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": scope_str,
        "access_type": "offline",
        "include_granted_scopes": "true",
        "prompt": "consent",
        "state": state,
    }
    return f"{GOOGLE_AUTH_URI}?{urlencode(params)}"

def _oauth_exchange_code(code: str, redirect_path: str) -> Tuple[Optional[Dict[str, Any]], str]:
    ok, reason = _google_oauth_ready()
    if not ok:
        return None, reason
    redirect_uri = f"{PUBLIC_BASE_URL}{redirect_path}"
    try:
        r = requests.post(
            GOOGLE_TOKEN_URI,
            data={
                "code": code,
                "client_id": GOOGLE_CLIENT_ID,
                "client_secret": GOOGLE_CLIENT_SECRET,
                "redirect_uri": redirect_uri,
                "grant_type": "authorization_code",
            },
            timeout=20,
        )
        data = r.json() if r.content else {}
        if r.status_code >= 400:
            return None, f"Token exchange failed: {data}"
        # Normalize expiry
        expires_in = int(data.get("expires_in") or 0)
        if expires_in:
            data["expires_at"] = _now_epoch() + max(0, expires_in - 30)
        return data, ""
    except Exception as e:
        return None, f"Token exchange error: {e}"

def _oauth_refresh_token(refresh_token: str, scopes: List[str]) -> Tuple[Optional[Dict[str, Any]], str]:
    ok, reason = _google_oauth_ready()
    if not ok:
        return None, reason
    try:
        r = requests.post(
            GOOGLE_TOKEN_URI,
            data={
                "client_id": GOOGLE_CLIENT_ID,
                "client_secret": GOOGLE_CLIENT_SECRET,
                "refresh_token": refresh_token,
                "grant_type": "refresh_token",
            },
            timeout=20,
        )
        data = r.json() if r.content else {}
        if r.status_code >= 400:
            if data.get("error") == "invalid_grant":
                return None, "__INVALID_GRANT__"
            return None, f"Token refresh failed: {data}"
        # Default to a conservative ~55 min when the provider omits expires_in,
        # so expires_at is always populated and refresh logic stays correct.
        expires_in = int(data.get("expires_in") or 0) or 3300
        data["expires_at"] = _now_epoch() + max(0, expires_in - 30)
        # refresh response often doesn't include refresh_token; keep the old one
        data.setdefault("refresh_token", refresh_token)
        return data, ""
    except Exception as e:
        return None, f"Token refresh error: {e}"

def _token_expired(token_info: Dict[str, Any]) -> bool:
    try:
        exp = int(token_info.get("expires_at") or 0)
        if exp <= 0:
            # Unknown expiry: treat as expired so a refresh is attempted. The
            # caller only refreshes when a refresh_token exists, so genuinely
            # non-expiring tokens (no refresh_token) are left alone.
            return bool(token_info.get("refresh_token"))
        return _now_epoch() >= exp
    except Exception:
        return False

def _get_access_token_from_store(token_info: Dict[str, Any], scopes: List[str]) -> Tuple[Optional[str], Optional[Dict[str, Any]], str]:
    if not token_info:
        return None, None, "Not connected."
    # refresh if needed
    if _token_expired(token_info) and token_info.get("refresh_token"):
        refreshed, err = _oauth_refresh_token(token_info.get("refresh_token"), scopes)
        if not refreshed:
            return None, None, err or "Token refresh failed."
        return refreshed.get("access_token"), refreshed, ""
    return token_info.get("access_token"), None, ""



# Global OPENAI_API_KEY optional; users will provide their own keys

client = None  # lazy init to avoid import time crashes
_CLIENT_LOCK = threading.Lock()

def _get_global_openai_client() -> "OpenAI":
    global client
    if client is None:
        with _CLIENT_LOCK:
            # Double-checked locking: re-test inside the lock in case another
            # thread initialised it while we were waiting.
            if client is None:
                client = OpenAI(api_key=(OPENAI_API_KEY or ""))
    return client

def _get_claude_client_for_user(u: Optional[Dict[str, Any]]) -> Optional[Any]:
    """Returns Anthropic client. Prefers user's own saved claude_key; falls back to server ANTHROPIC_API_KEY."""
    key = ""
    if u:
        key = _decrypt_field(((u.get("settings") or {}).get("claude_key") or "").strip())
    if not key:
        key = (ANTHROPIC_API_KEY or "").strip()
    if not key:
        return None
    sdk = _ensure_anthropic()
    if sdk is None:
        return None
    # Explicit timeout so a hung upstream connection (e.g. provider stalls
    # before the first token) can't pin a worker forever.
    try:
        return sdk.Anthropic(api_key=key, timeout=90.0)
    except TypeError:
        # Older SDK without a timeout kwarg.
        return sdk.Anthropic(api_key=key)

def _is_claude_model(model: Optional[str]) -> bool:
    return (model or "").lower().startswith("claude")

def _resolve_model_for_user(defn: Dict[str, Any], u: Optional[Dict[str, Any]] = None) -> str:
    """Priority: teammate preferred_model > user global_default_model > server MODEL."""
    tm = (defn.get("preferred_model") or "").strip()
    if tm:
        return tm
    if u:
        gm = ((u.get("settings") or {}).get("global_default_model") or "").strip()
        if gm:
            return gm
    return MODEL

