def _migrate_global_registry_once() -> None:
    """
    One-time migration: if the old global teammates.json has custom teammates
    (anything not in PREBUILT_LOCKED / DEFAULT_ORDER), copy them into the
    admin user's per-user registry. Runs at startup, safe to call repeatedly.
    """
    if not REGISTRY_PATH.exists():
        return
    try:
        old = json.loads(REGISTRY_PATH.read_text(encoding="utf-8"))
    except Exception:
        return

    old_installed = old.get("installed") or {}
    # Find custom teammates (not built-in)
    custom = {k: v for k, v in old_installed.items() if k not in DEFAULT_ORDER}
    if not custom:
        return  # nothing to migrate

    # Find the admin username (first created user)
    try:
        users_data = load_json(USERS_PATH, {})
        users = users_data.get("users") or {}
        if not users:
            return
        admin = _legacy_first_username(users)
        if not admin:
            return
    except Exception:
        return

    admin_path = _user_registry_path(admin)
    if admin_path.exists():
        try:
            existing = json.loads(admin_path.read_text(encoding="utf-8"))
        except Exception:
            existing = {"installed": {}, "installed_order": [], "active_order": []}
    else:
        existing = {"installed": {}, "installed_order": [], "active_order": []}

    changed = False
    for name, defn in custom.items():
        if name not in existing["installed"]:
            existing["installed"][name] = defn
            if name not in existing.get("installed_order", []):
                existing.setdefault("installed_order", []).append(name)
            if name not in existing.get("active_order", []):
                existing.setdefault("active_order", []).append(name)
            changed = True

    if changed:
        existing["updated_at"] = datetime.utcnow().isoformat() + "Z"
        admin_path.write_text(json.dumps(existing, indent=2), encoding="utf-8")

# =========================
# IMAGE JOBS (non-blocking, disk-persistent)
# =========================
# Hosting platforms often kill long-running requests. Image generation can exceed request timeouts.
# So we run image generation in a background thread and let the UI poll for completion.
# Jobs are persisted to disk so they survive server restarts and deploys.
IMAGE_JOBS: Dict[str, Dict[str, Any]] = {}
IMAGE_JOBS_LOCK = threading.Lock()
_JOBS_DIR = None  # set after DATA is defined below

def _jobs_dir() -> "Path":
    global _JOBS_DIR
    if _JOBS_DIR is None:
        _JOBS_DIR = DATA / "jobs"
        try:
            _JOBS_DIR.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
    return _JOBS_DIR

def _job_path(job_id: str) -> "Path":
    return _jobs_dir() / f"img_{job_id}.json"

def _image_job_set(job_id: str, patch: Dict[str, Any]) -> None:
    with IMAGE_JOBS_LOCK:
        cur = IMAGE_JOBS.get(job_id) or {}
        cur.update(patch or {})
        IMAGE_JOBS[job_id] = cur
    # Persist to disk atomically (tmp + rename) so a crash or a concurrent
    # write from another worker can't leave a half-written / corrupt job file
    # that makes the status poll silently return {} (spinner that never ends).
    try:
        save_json(_job_path(job_id), IMAGE_JOBS.get(job_id) or {})
    except Exception:
        pass

def _image_job_get(job_id: str) -> Dict[str, Any]:
    with IMAGE_JOBS_LOCK:
        if job_id in IMAGE_JOBS:
            return dict(IMAGE_JOBS[job_id])
    # Not in memory — try disk (survives restarts)
    try:
        p = _job_path(job_id)
        if p.exists():
            data = json.loads(p.read_text(encoding="utf-8"))
            with IMAGE_JOBS_LOCK:
                IMAGE_JOBS[job_id] = data
            return dict(data)
    except Exception:
        pass
    return {}

def _load_persisted_jobs() -> None:
    """On startup: load recent job files from disk into memory so status polls work after restart."""
    try:
        jd = _jobs_dir()
        cutoff = datetime.utcnow() - timedelta(hours=4)
        for p in jd.glob("img_*.json"):
            try:
                data = json.loads(p.read_text(encoding="utf-8"))
                created_str = str(data.get("created_at") or "")
                if created_str:
                    created_dt = datetime.fromisoformat(created_str.replace("Z", ""))
                    if created_dt < cutoff:
                        p.unlink(missing_ok=True)
                        continue
                # Mark any running/queued jobs as error — they died mid-generation on restart
                if data.get("status") in ("running", "queued"):
                    data["status"] = "error"
                    data["error"] = "Server restarted during generation. Please try again."
                    data["stage_label"] = "❌ Server restarted"
                    save_json(p, data)
                job_id = p.stem.replace("img_", "")
                with IMAGE_JOBS_LOCK:
                    IMAGE_JOBS[job_id] = data
            except Exception:
                pass
    except Exception:
        pass

def _image_jobs_evict_old(max_age_hours: int = 2) -> None:
    """Remove completed/errored image jobs older than max_age_hours, plus any orphaned
    queued/running jobs older than 1 hour (client disconnected mid-generation)."""
    try:
        cutoff_done = datetime.utcnow() - timedelta(hours=max_age_hours)
        cutoff_orphan = datetime.utcnow() - timedelta(hours=1)
        with IMAGE_JOBS_LOCK:
            stale = []
            for jid, job in IMAGE_JOBS.items():
                created_str = str(job.get("created_at") or "")
                if not created_str:
                    stale.append(jid)
                    continue
                try:
                    created_dt = datetime.fromisoformat(created_str.replace("Z", ""))
                except Exception:
                    stale.append(jid)
                    continue
                if job.get("status") in ("done", "error") and created_dt < cutoff_done:
                    stale.append(jid)
                elif job.get("status") in ("queued", "running") and created_dt < cutoff_orphan:
                    stale.append(jid)
            for jid in stale:
                IMAGE_JOBS.pop(jid, None)
                try:
                    _job_path(jid).unlink(missing_ok=True)
                except Exception:
                    pass
    except Exception:
        pass

def _thread_replace_or_append_image_note(teammate: str, job_id: str, final_note: str, username: str = "") -> None:
    try:
        uname = username or _get_session_username()
        thread = load_thread(teammate, uname)
        replaced = False
        for i in range(len(thread)-1, -1, -1):
            msg = thread[i] or {}
            if (msg.get("role") == "assistant") and (f"job:{job_id}" in (msg.get("content") or "")):
                thread[i] = {"role": "assistant", "content": final_note}
                replaced = True
                break
        if not replaced:
            thread.append({"role": "assistant", "content": final_note})
        save_thread(teammate, thread, uname)
    except Exception:
        pass

def _run_image_job(job_id: str, raw_prompt: str, teammate: str, username: str, lighting_mode: bool, mode: str = "new", source_file_id: str = "") -> None:
    import threading as _thr
    _image_job_set(job_id, {"status": "running", "stage": "refining_prompt", "stage_label": "✨ Refining your prompt..."})
    try:
        with app.app_context():
            _image_job_set(job_id, {"status": "running", "stage": "generating", "stage_label": "🎨 Generating image..."})
            rec, url, err = generate_image_for_teammate(raw_prompt, teammate=teammate, username=username, lighting_mode=lighting_mode, mode=mode, source_file_id=source_file_id)
            # Capture refined prompt that generate_image_for_teammate stored
            with _LAST_REFINED_PROMPT_LOCK:
                refined = _LAST_REFINED_PROMPT.pop(str(_thr.current_thread().ident), "") or raw_prompt
        if err or not url:
            _image_job_set(job_id, {"status": "error", "stage": "error", "stage_label": "❌ Generation failed", "error": err or "Image generation failed"})
            _thread_replace_or_append_image_note(teammate, job_id, f"[Image failed] {err or 'Image generation failed'}", username=username)
            return
        _image_job_set(job_id, {"status": "done", "stage": "done", "stage_label": "✅ Done!", "url": url, "image": rec, "refined_prompt": refined})
        try:
            _prior_thread = load_thread(teammate, username or _get_session_username())
            _ordinal = sum(1 for m in _prior_thread if isinstance(m, dict) and "[Image generated #" in (m.get("content") or "")) + 1
        except Exception:
            _ordinal = 1
        note = f"[Image generated #{_ordinal}] {url}"
        _desc = (refined or raw_prompt or "").strip()
        if _desc:
            note += f"\n[refined_prompt] {_desc}"
        _thread_replace_or_append_image_note(teammate, job_id, note, username=username)
        try: _increment_msg_usage(username, images=True)
        except Exception: pass
    except Exception as e:
        _image_job_set(job_id, {"status": "error", "stage": "error", "stage_label": "❌ Generation failed", "error": str(e) or "Image generation failed"})
        _thread_replace_or_append_image_note(teammate, job_id, f"[Image failed] {str(e) or 'Image generation failed'}", username=username)

def create_image_job(raw_prompt: str, teammate: str, username: str, lighting_mode: bool, mode: str = "new", source_file_id: str = "") -> str:
    _image_jobs_evict_old()  # sweep stale jobs on every new creation
    # Image generation limit check
    try:
        _pk = _get_user_plan(username or "")
        _img_ok, _img_used, _img_lim, _img_own = _check_image_limit(username or "", _pk)
        if not _img_ok:
            _pn = (PLANS.get(_pk) or {}).get("name", "your plan")
            raise RuntimeError(
                f"You've used all {_img_lim} image generations included in {_pn} this month. "
                f"Upgrade your plan or add your own API key in Settings for unlimited images."
            )
    except RuntimeError:
        raise
    except Exception:
        pass
    job_id = uuid.uuid4().hex
    _image_job_set(job_id, {"status": "queued", "created_at": now_iso(), "teammate": teammate, "mode": mode, "source_file_id": source_file_id, "username": username or ""})
    t = threading.Thread(target=_run_image_job, args=(job_id, raw_prompt, teammate, username, lighting_mode, mode, source_file_id), daemon=True)
    t.start()
    return job_id

