@app.after_request
def _add_security_headers(response):
    # Skip restrictive security headers for extension API routes — they need open CORS
    if (request.path or "").startswith("/api/extension/") or (request.path or "").startswith("/extension/"):
        response.headers["Access-Control-Allow-Origin"]  = "*"
        response.headers["Access-Control-Allow-Headers"] = "Content-Type, X-SA-Extension-Key"
        response.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
        return response
    response.headers["X-Frame-Options"]        = "SAMEORIGIN"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Referrer-Policy"]        = "strict-origin-when-cross-origin"
    response.headers["Permissions-Policy"]     = "geolocation=(), camera=(self), microphone=(self)"
    # Prevent sensitive API responses from being cached by browsers/proxies
    if request.path.startswith("/api/") and request.method in ("GET", "POST"):
        if not response.headers.get("Cache-Control"):
            response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    if PUBLIC_BASE_URL.startswith("https://"):
        response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    # Content Security Policy — tightened for production
    # Allows: same-origin scripts/styles, CDN fonts, Stripe.js, inline styles needed by Flask templates
    csp = (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline' https://js.stripe.com https://accounts.google.com; "
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
        "font-src 'self' https://fonts.gstatic.com; "
        "img-src 'self' data: blob: https:; "
        "connect-src 'self' https://api.openai.com https://api.anthropic.com https://api.stripe.com; "
        "frame-src https://js.stripe.com; "
        "object-src 'none'; "
        "base-uri 'self';"
    )
    response.headers["Content-Security-Policy"] = csp
    return response


@app.after_request
def _compress_response(response):
    """Gzip compress responses >1KB for text/html, application/json, text/javascript, text/css."""
    if response.direct_passthrough:
        return response
    if response.status_code < 200 or response.status_code >= 300:
        return response
    if "Content-Encoding" in response.headers:
        return response
    accept_encoding = request.headers.get("Accept-Encoding", "")
    if "gzip" not in accept_encoding:
        return response
    ctype = response.content_type or ""
    compressible = any(t in ctype for t in ("text/html", "application/json", "text/javascript", "text/css", "text/plain", "application/javascript"))
    if not compressible:
        return response
    data = response.get_data()
    if len(data) < 1024:
        return response
    buf = io.BytesIO()
    with gzip.GzipFile(mode="wb", fileobj=buf, compresslevel=6) as gz:
        gz.write(data)
    compressed = buf.getvalue()
    if len(compressed) >= len(data):
        return response
    response.set_data(compressed)
    response.headers["Content-Encoding"] = "gzip"
    response.headers["Content-Length"] = len(compressed)
    response.headers.add("Vary", "Accept-Encoding")
    return response


# =========================
# CSRF PROTECTION
# =========================
# All state-changing requests (POST/PUT/PATCH/DELETE) from authenticated sessions
# must include a valid CSRF token via the X-CSRF-Token header.

# =========================
# TOTP TWO-FACTOR AUTHENTICATION (RFC 6238, no extra deps)
# =========================
# Users can enable 2FA in Settings. A secret is generated and shown as a QR URI.
# On login, if 2FA is enabled the session is marked pending_2fa until the code is verified.

def _totp_generate_secret() -> str:
    """Generate a random 20-byte base32 secret for TOTP."""
    return base64.b32encode(os.urandom(20)).decode("utf-8")

def _totp_hotp(key_b32: str, counter: int) -> int:
    """HMAC-based OTP (RFC 4226)."""
    try:
        key = base64.b32decode(key_b32.upper() + "=" * (-len(key_b32) % 8))
        msg = struct.pack(">Q", counter)
        h = hmac.new(key, msg, hashlib.sha1).digest()
        offset = h[-1] & 0x0F
        code = struct.unpack(">I", h[offset:offset + 4])[0] & 0x7FFFFFFF
        return code % 1_000_000
    except Exception:
        return -1

def _totp_code(secret: str, ts: int = 0) -> str:
    """Current TOTP code (30-second window). ts=0 means now."""
    t = int(time.time() // 30) + ts
    return f"{_totp_hotp(secret, t):06d}"

def _totp_verify(secret: str, code: str) -> bool:
    """Verify a 6-digit TOTP code. Accepts ±1 window for clock drift."""
    if not secret or not code:
        return False
    code = code.strip().replace(" ", "")
    if len(code) != 6 or not code.isdigit():
        return False
    for offset in (-1, 0, 1):
        if _totp_code(secret, offset) == code:
            return True
    return False

def _totp_uri(secret: str, username: str) -> str:
    """otpauth:// URI for QR code generation."""
    label = quote_plus(f"{APP_NAME}:{username}")
    issuer = quote_plus(APP_NAME)
    return f"otpauth://totp/{label}?secret={secret}&issuer={issuer}&algorithm=SHA1&digits=6&period=30"

def _user_has_2fa(u: dict) -> bool:
    totp = u.get("totp") or {}
    return bool(totp.get("enabled")) and bool(_decrypt_field(totp.get("secret", "") or ""))

def _get_2fa_pending_user() -> str:
    """Return username if session is mid-2FA verification."""
    return session.get("_2fa_pending_user", "")

# The token is issued per-session via GET /api/csrf_token.
# Stripe webhooks are explicitly exempt — they use HMAC signature verification instead.

_CSRF_EXEMPT_PATHS = {
    "/api/login", "/api/logout", "/api/reset_request", "/api/reset_password",
    "/api/register", "/api/me",
}
_CSRF_EXEMPT_PREFIXES = ("/stripe/", "/oauth/", "/static/", "/api/extension/")

def _csrf_token_for_session() -> str:
    """Return the CSRF token for the current session, creating one if absent."""
    token = session.get("_csrf_token")
    if not token:
        token = secrets.token_hex(32)
        session["_csrf_token"] = token
        session.modified = True
    return token

def _csrf_valid() -> bool:
    """Return True if the incoming request carries a valid CSRF token."""
    if request.method in ("GET", "HEAD", "OPTIONS"):
        return True
    path = request.path
    # Stripe webhook uses HMAC signature — exempt from session-based CSRF
    if path.startswith("/stripe/"):
        return True
    for prefix in _CSRF_EXEMPT_PREFIXES:
        if path.startswith(prefix):
            return True
    if path in _CSRF_EXEMPT_PATHS:
        return True
    expected = session.get("_csrf_token", "")
    if not expected:
        return False
    incoming = (
        request.headers.get("X-CSRF-Token")
        or request.headers.get("X-Csrftoken")
        or (request.get_json(silent=True) or {}).get("_csrf_token", "")
        or request.form.get("_csrf_token", "")
    )
    return bool(incoming) and hmac.compare_digest(expected, incoming)


@app.get("/robots.txt")
def robots_txt():
    """Block crawlers from API, admin, and user pages. Allow marketing pages."""
    base = (PUBLIC_BASE_URL or "").rstrip("/")
    content = f"""User-agent: *
Disallow: /api/
Disallow: /admin/
Disallow: /stripe/
Disallow: /getting-started
Disallow: /extension/
Disallow: /uploads/
Allow: /
Allow: /pricing
Allow: /showcase
Allow: /terms
Allow: /privacy
Allow: /login
Allow: /register

Sitemap: {base}/sitemap.xml
"""
    return content, 200, {"Content-Type": "text/plain; charset=utf-8"}


@app.get("/sitemap.xml")
def sitemap_xml():
    """XML sitemap for marketing pages."""
    base = (PUBLIC_BASE_URL or "").rstrip("/")
    from datetime import date
    today = date.today().isoformat()
    urls = [
        ("",          "1.0",  "daily"),
        ("/pricing",  "0.9",  "weekly"),
        ("/showcase", "0.8",  "weekly"),
        ("/terms",    "0.5",  "monthly"),
        ("/privacy",  "0.5",  "monthly"),
        ("/login",    "0.6",  "monthly"),
        ("/register", "0.7",  "monthly"),
    ]
    xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    for path, priority, freq in urls:
        xml += f"""  <url>
    <loc>{base}{path}</loc>
    <lastmod>{today}</lastmod>
    <changefreq>{freq}</changefreq>
    <priority>{priority}</priority>
  </url>\n"""
    xml += "</urlset>"
    return xml, 200, {"Content-Type": "application/xml; charset=utf-8"}


# ── PWA icons ──────────────────────────────────────────────────────────────────
# Generated at runtime so no static files are needed on Render.
def _pwa_icon_png(size: int) -> bytes:
    """Branded Simply Agentic icon: dark gradient bg + purple glow orb + 'SA' pixel text."""
    W = H = size
    # 7-row × 5-col pixel bitmaps (MSB = leftmost column)
    S_ROWS = [0b01111, 0b10000, 0b10000, 0b01110, 0b00001, 0b00001, 0b11110]
    A_ROWS = [0b01110, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001]

    unit = max(2, W * 66 // 1000)       # cell size ~6.6% of icon width
    gap  = max(1, W * 38 // 1000)       # gap between S and A
    lh   = 7 * unit                     # letter height
    lw   = 5 * unit + gap + 5 * unit    # total SA width
    py0  = (H - lh) // 2               # vertical center
    px0  = (W - lw) // 2               # horizontal center

    # Build flat text mask (1 = draw text pixel)
    mask = bytearray(W * H)
    for row in range(7):
        y0 = py0 + row * unit
        if y0 < 0 or y0 + unit > H:
            continue
        for col in range(5):
            bit = 1 << (4 - col)
            # S letter
            if S_ROWS[row] & bit:
                x0 = px0 + col * unit
                for dy in range(unit):
                    base = (y0 + dy) * W + x0
                    for dx in range(unit):
                        if 0 <= x0 + dx < W:
                            mask[base + dx] = 1
            # A letter
            if A_ROWS[row] & bit:
                x0 = px0 + 5 * unit + gap + col * unit
                for dy in range(unit):
                    base = (y0 + dy) * W + x0
                    for dx in range(unit):
                        if 0 <= x0 + dx < W:
                            mask[base + dx] = 1

    cx2 = cy2 = (W - 1) / 2.0
    orb_R2 = (W * 0.54) ** 2   # squared orb radius
    rows_out = bytearray()
    for y in range(H):
        rows_out.append(0)      # PNG filter byte
        dy2 = (y - cy2) ** 2
        ty  = y / H
        bg_r = 10 + int(8 * ty)
        bg_g = 7  + int(6 * ty)
        bg_b = 24 + int(6 * ty)
        for x in range(W):
            if mask[y * W + x]:
                rows_out.extend((230, 215, 255))   # near-white lavender text
            else:
                d2   = (x - cx2) ** 2 + dy2
                r, g, b = bg_r, bg_g, bg_b
                if d2 < orb_R2:
                    glow = (1.0 - d2 / orb_R2) ** 1.5
                    r = min(255, r + int(100 * glow))
                    g = min(255, g + int(12  * glow))
                    b = min(255, b + int(195 * glow))
                rows_out.extend((r, g, b))

    def _chunk(tag: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(tag + data) & 0xffffffff
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", crc)
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)  # 8-bit RGB
    idat = zlib.compress(bytes(rows_out), 6)
    return b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", ihdr) + _chunk(b"IDAT", idat) + _chunk(b"IEND", b"")

# Cache icons at module level so they're only generated once per process
_PWA_ICON_180 = _pwa_icon_png(180)
_PWA_ICON_192 = _pwa_icon_png(192)
_PWA_ICON_512 = _pwa_icon_png(512)

