@app.get("/api/debug/key_status")
def api_debug_key_status():
    """Admin-only debug — shows which OpenAI key the server will use."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    if not _is_admin_user(u): return jsonify({"ok": False, "error": "Admin only"}), 403
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    u_record = load_users().get("users", {}).get(uname, {})
    raw_key = (u_record.get("settings") or {}).get("openai_key", "")
    decrypted = _decrypt_field(raw_key.strip()) if raw_key else ""
    server_key = OPENAI_API_KEY or ""
    effective = decrypted or server_key
    def mask(k): return (k[:8] + "..." + k[-4:]) if len(k) > 12 else ("set" if k else "empty")
    return jsonify({
        "ok": True,
        "user_key_stored": bool(raw_key),
        "user_key_decrypts": bool(decrypted),
        "user_key_preview": mask(decrypted),
        "server_key_set": bool(server_key),
        "server_key_preview": mask(server_key),
        "effective_key_preview": mask(effective),
        "will_use": "user_key" if decrypted else ("server_key" if server_key else "none"),
    })


    """Health check for Render and any uptime monitors.
    Returns 200 OK immediately — no auth, no DB calls, no overhead."""
    return jsonify({
        "status": "ok",
        "app":    APP_TITLE,
        "ts":     now_iso(),
    })

