# _adjust_content_length_for_video removed — modifying global app.config per-request
# is NOT thread-safe and causes a race condition where concurrent requests reset the
# limit to 25 MB mid-upload, killing the connection with a 413 and "Failed to fetch".
# The global ceiling is now 500 MB; individual routes enforce their own size limits.

@app.errorhandler(413)
def _handle_413(e):
    try:
        if (request.path or "").startswith("/api/"):
            return jsonify({"ok": False, "error": "File too large. Maximum upload size is 500 MB."}), 413
    except Exception:
        pass
    raise e

@app.before_request
def _auth_guard() -> Optional[Any]:
    if request.path in ("/login", "/setup", "/reset", "/reset/confirm", "/reset_password", "/register", "/static", "/terms", "/privacy", "/pricing", "/showcase", "/verify", "/verify/resend", "/health", "/ping"):
        return None
    if request.path.startswith("/static/"):
        return None
    if request.path.startswith("/stripe/"):
        return None
    if request.path.startswith("/admin/"):
        # Enforce auth globally for all admin routes — don't rely on per-route checks
        _au = current_user()
        if not _au or not _is_admin_user(_au):
            return redirect(url_for("login"))
        return None

    # allow setup if no users exist
    if request.path.startswith("/setup") and not has_any_user():
        return None

    public_api = {"/api/login", "/api/logout", "/api/reset_request", "/api/reset_password", "/api/me", "/api/csrf_token", "/api/register", "/health", "/ping"}
    if request.path.startswith("/api/") and request.path in public_api:
        return None

    # CSRF check — runs for all authenticated POST/PUT/PATCH/DELETE requests
    if not _csrf_valid():
        if request.path.startswith("/api/"):
            return jsonify({"ok": False, "error": "Invalid or missing CSRF token. Refresh the page and try again."}), 403
        return "Forbidden — invalid CSRF token", 403

    # Clear stale sessions so the login gate shows cleanly instead of half-auth states.
    if session.get("user") and not current_user():
        try:
            session.pop("user", None)
        except Exception:
            pass
        session.modified = True

    if request.path.startswith("/api/") and not current_user():
        resp = jsonify({"ok": False, "error": "Not authenticated"})
        resp.headers["Cache-Control"] = "no-store"
        return resp, 401

    if request.path == "/" and not current_user():
        if not has_any_user():
            return redirect(url_for("setup"))
        return redirect(url_for("login"))

    # attach per-user OpenAI client for this request (best-effort — skip if no key configured)
    u = current_user()
    user_key = ""
    if u:
        user_key = _decrypt_field((((u.get("settings") or {}).get("openai_key")) or "").strip())
    _effective_key = user_key or OPENAI_API_KEY
    if _effective_key:
        try:
            g.openai_client = OpenAI(api_key=_effective_key)
        except Exception:
            g.openai_client = None
    else:
        g.openai_client = None

    return None

def get_openai_client() -> "OpenAI":
    c = getattr(g, "openai_client", None)
    return c or _get_global_openai_client()

