    {"key": "operator_profile",  "title": "Complete Your Operator Profile"},
    {"key": "preferred_ai",      "title": "Add Your Own API Key (Optional)"},
    {"key": "full_team",         "title": "Install the Full Team"},
    {"key": "session_goal",      "title": "Set a Session Goal"},
