def _parse_local_dt(dt_local: str) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(dt_local)
    except Exception:
        return None

def _safe_render(template: str, ctx: Dict[str, Any]) -> str:
    out = template or ""
    for k, v in (ctx or {}).items():
        out = out.replace("{{" + k + "}}", str(v))
    return out

def _call_teammate_prompt_for_user(u: str, teammate: str, prompt: str, file_ids: Optional[List[str]] = None) -> str:
    file_ids = file_ids or []
    # Use existing followup core if available
    try:
        if "_execute_followup_core" in globals():
            try:
                res = _execute_followup_core(teammate, prompt, file_ids=file_ids, user_override=u)  # type: ignore[name-defined]
            except TypeError:
                res = _execute_followup_core(teammate, prompt, file_ids=file_ids)  # type: ignore[name-defined]
            return (res or {}).get("reply", "") or ""
    except Exception:
        pass

    reg = load_registry(_get_session_username())
    defn = (reg.get("installed") or {}).get(teammate)
    if not defn:
        return ""
    # lighting_mode is not available in this context — use False (safe default)
    sys_prompt = teammate_system_prompt(defn, lighting_mode=False)
    msg2, _, vision_images = build_prompt_with_attachments(prompt, file_ids)
    user_content = _build_user_content(msg2, vision_images)
    preferred_model = (defn.get("preferred_model") or "").strip() or None
    return call_llm(sys_prompt, [{"role": "user", "content": user_content}], temperature=0.65, model=preferred_model)

def _init_run(u: str, teammate: str, stack_name: str, steps: List[Dict[str, Any]], user_input: str) -> Dict[str, Any]:
    run_id = uuid.uuid4().hex
    return {
        "id": run_id,
        "user": u,
        "teammate": teammate,
        "stack_name": stack_name,
        "created_at": now_iso(),
        "status": "running",
        "cursor": 0,
        "error": "",
        "input": user_input or "",
        "steps": steps,
        "outputs": {},
        "log": [],
    }

def _persist_run(run: Dict[str, Any]) -> None:
    u = run.get("user") or "anon"
    runs = _load_runs(u)
    runs.setdefault("runs", {})
    runs["runs"][run["id"]] = run
    _save_runs(u, runs)

def _append_run_log(run: Dict[str, Any], event: str, data: Dict[str, Any]) -> None:
    run.setdefault("log", [])
    run["log"].append({"ts": now_iso(), "event": event, "data": data})

def _user_now_local(username: str) -> datetime:
    """Return current datetime in the user's configured timezone (UTC fallback)."""
    try:
        from zoneinfo import ZoneInfo
        tz_str = (_load_operator_profile(username) or {}).get("timezone") or "UTC"
        return datetime.now(ZoneInfo(tz_str)).replace(tzinfo=None)
    except Exception:
        return datetime.utcnow()

def _run_due_schedules_once() -> None:
    if not ACTION_STACK_SCHEDULES_DIR.exists():
        return
    for user_dir in ACTION_STACK_SCHEDULES_DIR.iterdir():
        if not user_dir.is_dir():
            continue
        u = user_dir.name
        now_local = _user_now_local(u)
        schedules = _load_schedules(u)
        if not schedules:
            continue
        changed = False
        for s in schedules:
            try:
                teammate = s.get("teammate") or ""
                stack_name = s.get("stack_name") or ""
                mode = s.get("mode") or ""
                last_run = s.get("last_run")
                due = False

                if mode == "once":
                    dt = _parse_local_dt(s.get("run_at") or "")
                    if dt and now_local >= dt and not last_run:
                        due = True
                elif mode == "daily":
                    t = s.get("time") or ""
                    if re.match(r"^\d{2}:\d{2}$", t):
                        hh, mm = t.split(":")
                        target = now_local.replace(hour=int(hh), minute=int(mm), second=0, microsecond=0)
                        if abs((now_local - target).total_seconds()) <= 45:
                            if last_run:
                                try:
                                    lr = datetime.fromisoformat(str(last_run).replace("Z",""))
                                    due = (lr.date() != now_local.date())
                                except Exception:
                                    due = True
                            else:
                                due = True

                if not due:
                    continue

                data = _load_saved_stacks(u, teammate)
                stack = (data.get("stacks") or {}).get(stack_name)
                if not stack:
                    continue
                steps = _normalize_steps(stack.get("steps"))
                run = _init_run(u=u, teammate=teammate, stack_name=stack_name, steps=steps, user_input="")
                _persist_run(run)
                _run_action_stack_engine(run)

                # Store last_run in the user's LOCAL frame so the daily dedupe
                # (lr.date() vs now_local.date()) doesn't double-run or skip
                # near midnight for non-UTC timezones.
                s["last_run"] = now_local.isoformat()
                changed = True
            except Exception:
                continue
        if changed:
            _save_schedules(u, schedules)

def _resume_due_runs_once() -> None:
    """Resume any waiting runs that are due."""
    if not ACTION_STACK_RUNS_DIR.exists():
        return
    now_utc = datetime.utcnow()
    for user_dir in ACTION_STACK_RUNS_DIR.iterdir():
        if not user_dir.is_dir():
            continue
        u = user_dir.name
        runs_data = _load_runs(u)
        runs = runs_data.get("runs") or {}
        changed = False
        for rid, run in list(runs.items()):
            try:
                if not isinstance(run, dict):
                    continue
                if run.get("status") != "waiting":
                    continue
                w = run.get("wait_until")
                if not w:
                    continue
                try:
                    w_dt = datetime.fromisoformat(str(w).replace("Z", ""))
                except Exception:
                    w_dt = None
                if w_dt and now_utc >= w_dt:
                    run["status"] = "running"
                    run.pop("wait_until", None)
                    runs[rid] = _run_action_stack_engine(run)
                    changed = True
            except Exception:
                continue
        if changed:
            runs_data["runs"] = runs
            _save_runs(u, runs_data)


# =========================
# CORE FRAMEWORK (ENFORCED)
# =========================

DEFAULT_CORE_FRAMEWORK_TEXT = """
CORE OPERATING PRINCIPLES

Act with autonomy. Read the request, understand the goal, and move. Do not wait for permission to be useful. If something is genuinely unclear or has real downstream risk, surface it in ONE sentence — then still give your best attempt.

Adapt in real time. If the user corrects you, updates the goal, or gives new context, shift immediately. Do not repeat a pattern that stopped working.

Stay aligned. Every response should serve the operator's actual goal, not just the literal words of the last message. If you notice a mismatch between what they asked and what they need, name it briefly — then do both.

Be a thinking partner. Bring your own judgment. Push back when you see a better path — once, clearly, without lecturing. Then execute what they decide.

Protect memory integrity. Never invent facts about the user, their business, or past conversations. If memory context is provided, treat it as established ground truth. If it's not provided, don't fabricate it.

Own uncertainty cleanly. If you're not sure, say so in one plain sentence. Then give your best read anyway. Uncertainty is not a reason to stall — it's a reason to flag and proceed.

GROUP ACTIVATION & TEAM ASSEMBLY
When the user says "All teammates to the round table" or activates a group session:
- Every active teammate announces their Name, Job Title, and Version
- No one executes tasks during assembly
- Wait for the next instruction before acting
""".strip()


def load_core_framework() -> str:
    try:
        if FRAMEWORK_PATH.exists():
            txt = FRAMEWORK_PATH.read_text(encoding="utf-8", errors="replace").strip()
            return txt if txt else DEFAULT_CORE_FRAMEWORK_TEXT
    except Exception:
        pass
    return DEFAULT_CORE_FRAMEWORK_TEXT


def save_core_framework(text: str) -> None:
    cleaned = (text or "").strip()
    if not cleaned:
        cleaned = DEFAULT_CORE_FRAMEWORK_TEXT
    # Snapshot the current version to history before overwriting (keep last 10)
    try:
        _fw_hist_path = DATA / "core_framework_history.json"
        _fw_lock = _json_file_lock(_fw_hist_path)
        with _fw_lock:
            try:
                _hist = json.loads(_fw_hist_path.read_text(encoding="utf-8")) if _fw_hist_path.exists() else []
                if not isinstance(_hist, list):
                    _hist = []
            except Exception:
                _hist = []
            if FRAMEWORK_PATH.exists():
                _prev = FRAMEWORK_PATH.read_text(encoding="utf-8", errors="replace").strip()
                if _prev:
                    _hist.insert(0, {"ts": now_iso(), "text": _prev})
                    _hist = _hist[:10]
            _tmp = _fw_hist_path.with_suffix(".tmp")
            _tmp.write_text(json.dumps(_hist, indent=2), encoding="utf-8")
            _tmp.replace(_fw_hist_path)
    except Exception:
        pass
    # Atomic write for the framework itself
    try:
        _tmp2 = FRAMEWORK_PATH.with_suffix(".tmp")
        _tmp2.write_text(cleaned, encoding="utf-8")
        _tmp2.replace(FRAMEWORK_PATH)
    except Exception:
        FRAMEWORK_PATH.write_text(cleaned, encoding="utf-8")

# Ensure the framework file always exists with the default framework for local-first users.
try:
    if (not FRAMEWORK_PATH.exists()) or (not FRAMEWORK_PATH.read_text(encoding="utf-8", errors="replace").strip()):
        FRAMEWORK_PATH.write_text(DEFAULT_CORE_FRAMEWORK_TEXT, encoding="utf-8")
except Exception:
    pass


