# REGISTRY + THREADS
# =========================

def _registry_defaults() -> Dict[str, Any]:
    return {"installed": {}, "installed_order": [], "active_order": [], "updated_at": None}


def load_registry(username: str = "") -> Dict[str, Any]:
    """Load per-user teammate registry. Built-ins always present; custom ones are per-user."""
    uname = username or _get_session_username()
    path  = _user_registry_path(uname)
    reg   = load_json(path, _registry_defaults()) if path.exists() else _registry_defaults()
    if not isinstance(reg, dict):
        reg = _registry_defaults()

    reg.setdefault("installed", {})
    reg.setdefault("installed_order", [])
    reg.setdefault("active_order", [])

    installed = reg.get("installed") or {}

    # Always inject all built-ins — they can never be missing.
    # If a built-in is already installed but its version doesn't match PREBUILT_LOCKED,
    # merge the canonical definition while preserving custom user fields (preferred_model, last_used_at).
    _PRESERVE_USER_FIELDS = {"preferred_model", "last_used_at", "custom_notes"}
    for name in DEFAULT_ORDER:
        canonical = PREBUILT_LOCKED[name]
        if name not in installed:
            installed[name] = dict(canonical)
            if name not in reg["installed_order"]:
                reg["installed_order"].append(name)
        else:
            existing = installed[name]
            existing_ver = (existing.get("version") or "")
            canonical_ver = (canonical.get("version") or "")
            if existing_ver != canonical_ver:
                # Merge: take all canonical fields, restore user-specific ones
                merged = dict(canonical)
                for uf in _PRESERVE_USER_FIELDS:
                    if uf in existing:
                        merged[uf] = existing[uf]
                installed[name] = merged

    reg["installed"] = installed

    # Self-heal ordering
    installed_order = reg.get("installed_order") or []
    if installed and (not isinstance(installed_order, list) or len(installed_order) == 0):
        rebuilt: List[str] = []
        for n in DEFAULT_ORDER:
            if n in installed and n not in rebuilt:
                rebuilt.append(n)
        for n in installed.keys():
            if n not in rebuilt:
                rebuilt.append(n)
        reg["installed_order"] = rebuilt

    if (not isinstance(reg.get("active_order"), list)) or (len(reg.get("active_order") or []) == 0):
        reg["active_order"] = list(reg.get("installed_order") or [])

    reg["active_order"] = [n for n in (reg.get("active_order") or []) if n in installed]

    return reg


def save_registry(reg: Dict[str, Any], username: str = "") -> None:
    """Save per-user teammate registry."""
    uname = username or _get_session_username()
    path  = _user_registry_path(uname)
    reg["updated_at"] = now_iso()
    save_json(path, reg)


def install_full_team(username: str = "") -> Dict[str, Any]:
    uname = username or _get_session_username()
    reg = load_registry(uname)
    installed = reg["installed"]
    order = reg["installed_order"]

    for name in DEFAULT_ORDER:
        installed[name] = PREBUILT_LOCKED[name]
        if name not in order:
            order.append(name)

    reg["installed"] = installed
    reg["installed_order"] = order

    active = reg.get("active_order") or []
    for name in order:
        if name not in active:
            active.append(name)
    reg["active_order"] = active

    save_registry(reg, uname)
    return reg


def thread_path(teammate_name: str, username: str = "") -> Path:
    uname = username or _get_session_username()
    safe  = re.sub(r"[^a-zA-Z0-9_-]+", "_", teammate_name)
    return _user_threads_dir(uname) / f"{safe}.json"


def load_thread(teammate_name: str, username: str = "") -> List[Dict[str, str]]:
    return load_json(thread_path(teammate_name, username), [])


def _summarize_thread_segment(msgs: List[Dict[str, Any]]) -> str:
    """Compress a list of thread messages into a <=200 word summary using the LLM.
    Falls back to a keyword extract if the LLM call fails."""
    try:
        flat = []
        for m in msgs:
            role = (m.get("role") or "").strip()
            content = str(m.get("content") or "").strip()
            if content and role in ("user", "assistant"):
                flat.append(f"{role.upper()}: {content[:1500]}")
        combined = "\n".join(flat[:20])
        if not combined:
            return "earlier conversation"
        summary = call_llm(
            "You are a conversation summarizer. Summarize the following conversation excerpt in 150 words or fewer. "
            "Preserve all key decisions, facts, names, and action items. Be dense and factual. No preamble.",
            [{"role": "user", "content": combined}],
            temperature=0.2,
        )
        return summary.strip() or "earlier conversation"
    except Exception:
        # Fallback: extract user message snippets without an API call
        topics = []
        for m in msgs:
            if (m.get("role") or "") == "user":
                snippet = str(m.get("content") or "")[:100].replace("\n", " ").strip()
                if snippet:
                    topics.append(snippet)
        return "; ".join(topics[:5]) if topics else "earlier conversation"


def _truncate_thread_with_note(thread: List[Dict[str, Any]], max_messages: int = 14) -> List[Dict[str, Any]]:
    """Keep max_messages most-recent turns. Dropped context is summarized via LLM
    and pinned as a system-style note so the AI retains the thread's history."""
    if len(thread) <= max_messages:
        return thread
    dropped = thread[:-max_messages]
    kept    = thread[-max_messages:]
    summary = _summarize_thread_segment(dropped)
    note = (
        f"[Earlier conversation summary ({len(dropped)} messages trimmed): {summary}]"
    )
    _img_lines = []
    for _m in dropped:
        _c = (_m or {}).get("content") or ""
        if isinstance(_c, str) and "[Image generated #" in _c:
            _img_lines.append(_c.split("\n[refined_prompt]")[0].strip().splitlines()[0])
    if _img_lines:
        note += "\n[Images generated earlier (still relevant — see RECENT IMAGES section for descriptions): " + "; ".join(_img_lines) + "]"
    return [
        {"role": "user",      "content": note},
        {"role": "assistant", "content": "Understood — I have that earlier context and will keep it in mind."},
    ] + kept


_SEARCH_INDEX: Dict[str, Any] = {}  # uname -> {"index": {word -> [(tm, msg_idx, snippet)]}, "ts": float}
_SEARCH_INDEX_LOCK = threading.Lock()
_SEARCH_INDEX_TTL = 60.0

def _invalidate_search_index(uname: str) -> None:
    with _SEARCH_INDEX_LOCK:
        _SEARCH_INDEX.pop(uname, None)

def _build_search_index(uname: str, installed: Dict[str, Any]) -> Dict[str, Any]:
    """Build a word -> [(teammate, msg_idx, snippet)] index for instant search."""
    import time as _t
    with _SEARCH_INDEX_LOCK:
        cached = _SEARCH_INDEX.get(uname)
        if cached and (_t.monotonic() - cached["ts"]) < _SEARCH_INDEX_TTL:
            return cached["index"]
    # Build fresh index
    idx: Dict[str, List] = {}
    for tm_name in installed:
        try:
            thread = load_thread(tm_name, uname)
            for i, m in enumerate(thread):
                content = m.get("content") or ""
                if isinstance(content, list):
                    content = " ".join(str(c) for c in content)
                content_lower = content.lower()
                snippet = content[:300].replace("\n", " ")
                # Index 3-char+ words and bigrams
                words = re.findall(r'\b\w{3,}\b', content_lower)
                for w in set(words):
                    idx.setdefault(w, []).append((tm_name, m.get("role", "user"), i, snippet))
                # Index bigrams for phrase search
                for j in range(len(words) - 1):
                    bigram = words[j] + " " + words[j+1]
                    idx.setdefault(bigram, []).append((tm_name, m.get("role", "user"), i, snippet))
        except Exception:
            pass
    with _SEARCH_INDEX_LOCK:
        _SEARCH_INDEX[uname] = {"index": idx, "ts": __import__("time").monotonic()}
    return idx

def save_thread(teammate_name: str, msgs: List[Dict[str, str]], username: str = "") -> None:
    save_json(thread_path(teammate_name, username), msgs)
    # Invalidate search index so next search rebuilds fresh
    try:
        uname = username or _get_session_username()
        _invalidate_search_index(uname)
    except Exception:
        pass
    # [UPGRADE 4] Track last_used_at on the teammate's registry entry — additive, never breaks reads.
    # Throttle to at most once per ~5 min per teammate: last_used_at is only
    # used for sort/display, so we don't need to rewrite the whole registry
    # (a file write + lock) on every single chat message.
    try:
        uname = username or _get_session_username()
        reg   = load_registry(uname)
        installed = reg.get("installed") or {}
        if teammate_name in installed and isinstance(installed[teammate_name], dict):
            _prev = installed[teammate_name].get("last_used_at") or ""
            _stale = True
            if _prev:
                try:
                    if (datetime.utcnow() - datetime.fromisoformat(_prev.replace("Z", ""))).total_seconds() < 300:
                        _stale = False
                except Exception:
                    _stale = True
            if _stale:
                installed[teammate_name]["last_used_at"] = now_iso()
                reg["installed"] = installed
                save_registry(reg, uname)
    except Exception:
        pass  # tracking must never break saves


