# Storage helpers for custom prompts + usage tracking
PROMPT_LIBRARY_DIR = DATA / "prompt_library"
PROMPT_LIBRARY_DIR.mkdir(parents=True, exist_ok=True)

def _prompt_library_path(username: str) -> Path:
    return PROMPT_LIBRARY_DIR / f"{_safe_name(username or 'anon')}.json"

def _load_user_prompt_data(username: str) -> Dict[str, Any]:
    data = load_json(_prompt_library_path(username), {"custom": [], "usage": {}, "updated_at": None})
    if not isinstance(data, dict):
        data = {}
    data.setdefault("custom", [])
    data.setdefault("usage", {})
    if not isinstance(data["custom"], list):
        data["custom"] = []
    if not isinstance(data["usage"], dict):
        data["usage"] = {}
    return data

def _save_user_prompt_data(username: str, data: Dict[str, Any]) -> None:
    data["updated_at"] = now_iso()
    save_json(_prompt_library_path(username), data)

def _build_prompt_response(username: str, teammate_filter: str = "") -> Dict[str, Any]:
    """Merge built-ins + tiered packs (rank-gated) + user customs, optionally filter by teammate."""
    user_data = _load_user_prompt_data(username)
    usage     = user_data.get("usage") or {}
    custom    = user_data.get("custom") or []

    # Determine user tier for unlock gating
    try:
        pt_data   = _community_load_points()
        pt_total  = (pt_data.get(username) or {}).get("total", 0)
        user_tier = _get_user_rank(pt_total)["tier"]
    except Exception:
        user_tier = 1

    result: Dict[str, Any] = {}

    # Build a merged list of all prompts per teammate
    all_prompts: Dict[str, List[Dict[str, Any]]] = {}
    for tm, prompts in PROMPT_LIBRARY.items():
        if teammate_filter and tm != teammate_filter:
            continue
        all_prompts.setdefault(tm, [])
        for p in prompts:
            all_prompts[tm].append({**p, "builtin": True, "min_tier": 1, "locked": False})

    # Add tiered prompt packs — visible to all but locked above user's tier
    for p in TIERED_PROMPT_PACKS:
        tm = p.get("teammate", "")
        if teammate_filter and tm != teammate_filter:
            continue
        min_t = p.get("min_tier", 1)
        locked = user_tier < min_t
        all_prompts.setdefault(tm, []).append({**p, "builtin": True, "locked": locked})

    for tm, prompts in all_prompts.items():
        by_category: Dict[str, List[Dict[str, Any]]] = {}
        for p in prompts:
            cat   = p.get("category", "General")
            entry = dict(p)
            entry["teammate"]  = tm
            entry["use_count"] = int(usage.get(p.get("id",""), 0))
            by_category.setdefault(cat, []).append(entry)

        tm_customs = [c for c in custom if c.get("teammate") == tm]
        for c in tm_customs:
            cat   = c.get("category", "Custom")
            entry = dict(c)
            entry["use_count"] = int(usage.get(c.get("id",""), 0))
            entry.setdefault("locked", False)
            by_category.setdefault(cat, []).append(entry)

        result[tm] = {
            "teammate":   tm,
            "categories": by_category,
            "total":      len(prompts) + len(tm_customs),
            "user_tier":  user_tier,
        }

    return result



@app.get("/api/prompts")
def api_prompts_get():
    """Return all prompts (built-in + custom) with usage counts.
    Optional ?teammate=Alex to filter to a single teammate."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname    = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    teammate = (request.args.get("teammate") or "").strip()
    data     = _build_prompt_response(uname, teammate_filter=teammate)
    return jsonify({"ok": True, "prompts": data, "teammate_filter": teammate or None})


@app.post("/api/prompts")
def api_prompts_create():
    """Save a new custom prompt to the user's prompt library."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname   = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    payload = request.get_json(force=True, silent=True) or {}

    teammate = (payload.get("teammate") or "").strip()
    title    = (payload.get("title")    or "").strip()[:80]
    prompt   = (payload.get("prompt")   or "").strip()[:2000]
    category = (payload.get("category") or "Custom").strip()[:40]

    if not teammate:
        return jsonify({"ok": False, "error": "teammate is required"}), 400
    if not title:
        return jsonify({"ok": False, "error": "title is required"}), 400
    if not prompt:
        return jsonify({"ok": False, "error": "prompt is required"}), 400

    new_prompt = {
        "id":         "custom_" + uuid.uuid4().hex[:12],
        "teammate":   teammate,
        "title":      title,
        "prompt":     prompt,
        "category":   category,
        "builtin":    False,
        "created_at": now_iso(),
    }

    data = _load_user_prompt_data(uname)
    data["custom"].append(new_prompt)
    # Cap at 200 custom prompts per user
    if len(data["custom"]) > 200:
        data["custom"] = data["custom"][-200:]
    _save_user_prompt_data(uname, data)

    return jsonify({"ok": True, "prompt": {**new_prompt, "use_count": 0}})


@app.delete("/api/prompts/<prompt_id>")
def api_prompts_delete(prompt_id: str):
    """Delete a custom prompt. Built-in prompts cannot be deleted."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    # Protect built-ins
    for prompts in PROMPT_LIBRARY.values():
        if any(p["id"] == prompt_id for p in prompts):
            return jsonify({"ok": False, "error": "Built-in prompts cannot be deleted."}), 403

    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    data  = _load_user_prompt_data(uname)
    before = len(data["custom"])
    data["custom"] = [c for c in data["custom"] if c.get("id") != prompt_id]
    if len(data["custom"]) == before:
        return jsonify({"ok": False, "error": "Prompt not found"}), 404
    # Clean up usage tracking for deleted prompt
    data["usage"].pop(prompt_id, None)
    _save_user_prompt_data(uname, data)
    return jsonify({"ok": True})


@app.post("/api/prompts/<prompt_id>/use")
def api_prompts_use(prompt_id: str):
    """Record a prompt being used. Increments use_count for built-ins and custom prompts alike."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    data  = _load_user_prompt_data(uname)
    data["usage"][prompt_id] = int(data["usage"].get(prompt_id, 0)) + 1
    _save_user_prompt_data(uname, data)
    return jsonify({"ok": True, "prompt_id": prompt_id, "use_count": data["usage"][prompt_id]})


@app.get("/api/framework")
def api_get_framework():
    return jsonify({"ok": True, "framework": load_core_framework()})


@app.post("/api/framework")
def api_set_framework():
    data = request.get_json(force=True) or {}
    fw = (data.get("framework") or "").strip()
    save_core_framework(fw)
    append_log("framework_updated", {"updated_at": now_iso(), "length": len(load_core_framework())})
    return jsonify({"ok": True, "length": len(load_core_framework())})


@app.post("/api/install/full")
def api_install_full():
    uname = _get_session_username()
    reg = install_full_team(uname)
    try:
        _mark_onboarding_step(uname, "full_team", True)
    except Exception:
        pass
    return jsonify({"ok": True, "installed_order": reg["installed_order"], "active_order": reg.get("active_order") or []})


@app.post("/api/active_order")
def api_set_active_order():
    uname = _get_session_username()
    data = request.get_json(force=True) or {}
    order = data.get("active_order")
    if not isinstance(order, list):
        return jsonify({"ok": False, "error": "active_order must be a list"}), 400
    final = set_active_order(order, uname)
    append_log("active_order_set", {"active_order": final, "updated_at": now_iso()})
    return jsonify({"ok": True, "active_order": final})


@app.delete("/api/teammate/<n>")
def api_delete_teammate(n: str):
    """Permanently delete a custom teammate. Built-in teammates cannot be deleted."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    reg = load_registry(uname)
    installed = reg.get("installed", {})
    if n not in installed:
        return jsonify({"ok": False, "error": "Teammate not found"}), 404
    if n in PREBUILT_LOCKED:
        return jsonify({"ok": False, "error": f"\'{n}\' is a built-in teammate — use Dismiss to remove them from the table instead."}), 403
    installed.pop(n, None)
    reg["installed"] = installed
    reg["installed_order"] = [x for x in (reg.get("installed_order") or []) if x != n]
    reg["active_order"]    = [x for x in (reg.get("active_order") or []) if x != n]
    save_registry(reg, uname)
    try:
        tp = thread_path(n, uname)
        if tp.exists(): tp.unlink()
    except Exception:
        pass
    append_log("teammate_deleted", {"name": n, "deleted_by": uname, "at": now_iso()})
    _notif_push(uname, "Teammate removed", f"{n} has been uninstalled.", ntype="info")
    return jsonify({"ok": True})


@app.post("/api/teammate/create")
def api_create_teammate():
    uname = _get_session_username()
    data = request.get_json(force=True) or {}

    # Enforce plan-based custom teammate limit
    plan_key  = _get_user_plan(uname)
    plan_info = PLANS.get(_normalize_plan_key(plan_key)) or PLANS["solo"]
    max_custom = plan_info.get("custom_teammates")  # None = unlimited, 0 = not allowed

    if max_custom is not None:  # None means unlimited — skip check
        reg = load_registry(uname)
        installed = reg.get("installed") or {}
        current_custom = sum(1 for t in installed.values() if t.get("custom") or t.get("created_by"))
        if current_custom >= max_custom:
            plan_name = plan_info.get("name", "your plan")
            if max_custom == 0:
                return jsonify({
                    "ok": False,
                    "error": f"Custom teammates are not available on {plan_name}. Upgrade to Solo or Teams to create custom teammates. <a href='/pricing' style='color:#c4b5fd;'>View plans →</a>"
                }), 403
            else:
                return jsonify({
                    "ok": False,
                    "error": f"You've reached the {max_custom} custom teammate limit on {plan_name}. Upgrade to the Teams plan for unlimited custom teammates. <a href='/pricing' style='color:#c4b5fd;'>View plans →</a>"
                }), 403

    try:
        t = create_teammate(data, uname)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    append_log("teammate_created", {"name": t.get("name"), "job_title": t.get("job_title"), "version": t.get("version"), "created_at": now_iso()})
    _notif_push(uname, "Teammate created", f"{t.get('name','')} is installed and ready.", ntype="success")
    return jsonify({"ok": True, "teammate": t})


