@app.post("/api/convene")
def api_convene():
    rl = _check_rate_limit("convene", 30)  # 30 AI requests/min per user
    if rl:
        return rl
    try:
        data = request.get_json(force=True) or {}
    except Exception:
        data = {}
    prompt = (data.get("prompt") or "")
    if len(prompt) > MAX_PROMPT_CHARS:
        return jsonify({"ok": False, "error": f"Prompt exceeds {MAX_PROMPT_CHARS:,} character limit."}), 400
    try:
        return _api_convene_impl(data)
    except Exception as e:
        _capture_error(e, context="api_convene")
        try:
            append_log("convene_crash", {"error": str(e)})
        except Exception:
            pass
        r = jsonify({"ok": False, "error": "Request failed. Please try again."})
        r.headers["Content-Type"] = "application/json"
        return r, 500

def _api_convene_impl(data):
    prompt = (data.get("prompt") or "").strip()
    file_ids = data.get("file_ids") or []
    lighting_mode = bool(data.get("lighting_mode"))

    if not prompt:
        return jsonify({"ok": False, "error": "Missing prompt"}), 400

    reg = load_registry(_get_session_username())
    installed = reg["installed"]
    order = reg.get("active_order") or reg.get("installed_order") or []

    if not installed:
        return jsonify({"ok": False, "error": "No teammates installed"}), 400
    if not order:
        return jsonify({"ok": False, "error": "No active teammates in the round table"}), 400

    if is_assembly(prompt):
        roll = []
        for name in order:
            d = installed.get(name)
            if not d:
                continue
            roll.append({"name": d["name"], "job_title": d.get("job_title", ""), "version": d.get("version", "")})
        append_log("assembly", {"prompt": prompt, "roll": roll})
        return jsonify({"ok": True, "mode": "assembly", "roll": roll})

    try:
        uname = _get_session_username()
    except Exception:
        uname = "anon"

    # ── Usage-limit gate (mirrors api_followup_stream) ────────────────────────
    # Convene fans out to every active teammate — without this, a credit-
    # exhausted or keyless user could drive unbounded platform-key AI spend.
    try:
        _plan_k = _get_user_plan(uname)
        _allowed, _used, _limit, _iused, _ilimit, _own_key = _check_msg_limit(uname, _plan_k)
        if not _allowed:
            _plan_nm = (PLANS.get(_plan_k) or {}).get("name", "your plan")
            return jsonify({"ok": False, "error": (
                f"You've used all {_limit} AI Credits included in {_plan_nm} this month. "
                f"Upgrade to get more, or add your own API key in Settings for unlimited credits."
            ), "limit_hit": True}), 429
    except Exception:
        _own_key = _user_has_own_key(uname)

    # Protect the platform key: keyless users are clamped to gpt-4o-mini for
    # every call in this request (preflight + each teammate).
    _convene_force_model = None if _own_key else "gpt-4o-mini"

    prompt2, attach_meta, vision_images = build_prompt_with_attachments(prompt, file_ids)
    user_content = _build_user_content(prompt2, vision_images)

    atlis = installed.get("Atlis") or PREBUILT_LOCKED["Atlis"]
    atlis_sys = teammate_system_prompt(atlis, lighting_mode=lighting_mode)
    try:
        atlis_report = call_llm(
            atlis_sys,
        [{"role": "user", "content": json.dumps({
            "task": "Integrity preflight check",
            "rules": [
                "No execution. Report only.",
                "If unclear, recommend asking exactly one clarifying question.",
                "No em dashes."
            ],
            "user_prompt": prompt2
        }, indent=2)}],
        temperature=0.2,
        model=_convene_force_model
        )
        _increment_msg_usage(uname)
    except Exception as e:
        status, msg = _classify_openai_error(e)
        append_log("convene_error", {"where":"atlis_preflight","error": str(e)})
        return jsonify({"ok": False, "error": msg}), status

    # Task log: Atlis preflight (append-only)
    append_task_log(
        "atlis_preflight",
        {
            "prompt": prompt,
            "prompt_with_attachments": prompt2,
            "attachment_meta": attach_meta,
            "vision_images_count": len(vision_images),
            "report_preview": (atlis_report[:800] + ("..." if len(atlis_report) > 800 else "")),
        },
        teammate="Atlis",
        status="success"
    )

    outputs: Dict[str, str] = {}
    email_drafts: Dict[str, Dict[str, str]] = {}

    # Round-table roster so each teammate knows who covers what — prevents the
    # repetitive, overlapping "everyone gives the same generic plan" responses.
    _convene_roster = []
    for _rn in order:
        _rd = installed.get(_rn)
        if _rd:
            _convene_roster.append((_rd.get("name") or _rn, (_rd.get("job_title") or "").strip()))

    for name in order:
        defn = installed.get(name)
        if not defn:
            continue

        # Image requests are handled by the client-side /api/followup fanout which
        # creates a real image job. Skip the LLM here so we don't get a stale text
        # response ("I'll create it...") saved over the image placeholder.
        if is_image_request(prompt2):
            continue

        _role = (defn.get("job_title") or "specialist").strip() or "specialist"
        _others = "; ".join(f"{nm} ({jt})" for nm, jt in _convene_roster if nm != name) or "no other teammates"
        _convene_directive = (
            f"\n\nROUND-TABLE MODE: You are {name}, the {_role}, giving a group-console response "
            f"alongside other specialists, each covering their own domain: {_others}. "
            "Contribute ONLY your specialist's slice from your area of expertise — do NOT write a "
            "full general business plan or a broad overview that could have come from anyone. Do "
            "not cover ground that clearly belongs to another teammate's role; trust them to handle "
            "theirs. Be specific, distinct, and tightly focused on what only YOU bring. If the "
            "request falls largely outside your lane, give just the narrow part that genuinely fits "
            "your specialty rather than padding with generic advice."
        )
        sys = teammate_system_prompt(defn, lighting_mode=lighting_mode) + _convene_directive

        thread = _truncate_thread_with_note(load_thread(name, uname), max_messages=20)

        msgs: List[Dict[str, Any]] = []
        msgs.extend(thread)
        msgs.append({"role": "user", "content": user_content})

        # Keyless users are clamped to gpt-4o-mini to protect the platform key.
        _convene_model = _convene_force_model or _resolve_model_for_user(defn, current_user())
        try:
            text = call_llm(sys, msgs, temperature=0.65, model=_convene_model)
        except Exception as e:
            status, msg = _classify_openai_error(e)
            append_log("convene_error", {"where": name, "error": str(e)})
            return jsonify({"ok": False, "error": msg}), status

        # Meter every teammate response against the user's monthly credits.
        _increment_msg_usage(uname)

        new_thread = thread + [{"role": "user", "content": prompt2}, {"role": "assistant", "content": text}]
        save_thread(name, new_thread, uname)

        outputs[name] = text

        # Task log per teammate response (append-only)
        append_task_log(
            "teammate_convene",
            {
                "prompt": prompt,
                "prompt_with_attachments": prompt2,
                "attachment_meta": attach_meta,
                "vision_images_count": len(vision_images),
                "response_preview": (text[:800] + ("..." if len(text) > 800 else "")),
            },
            teammate=name,
            status="success"
        )

        d = extract_email_draft(text)
        if d:
            email_drafts[name] = d

    append_log("convene", {
        "prompt": prompt,
        "prompt_with_attachments": prompt2,
        "attachment_meta": attach_meta,
        "vision_images_count": len(vision_images),
        "order": order,
        "atlis_report": atlis_report,
        "framework_length": len(load_core_framework()),
        "outputs": outputs,
        "email_drafts": email_drafts,
    })

    # Extract shared team memory from this round's outputs (non-blocking background thread)
    try:
        uname_for_mem = _get_session_username()
        _extract_shared_memory_async(uname_for_mem, prompt, outputs)
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "mode": "execute",
        "atlis_report": atlis_report,
        "outputs": outputs,
        "email_drafts": email_drafts,
        "attachment_meta": attach_meta
    })


@app.post("/api/followup")
def api_followup():
    rl = _check_rate_limit("followup", 30)  # 30 AI requests/min per user
    if rl:
        return rl
    try:
        data = request.get_json(force=True) or {}
    except Exception:
        data = {}
    msg = (data.get("message") or "")
    if len(msg) > MAX_MESSAGE_CHARS:
        return jsonify({"ok": False, "error": f"Message exceeds {MAX_MESSAGE_CHARS:,} character limit."}), 400
    try:
        return _api_followup_impl(data)
    except Exception as e:
        _capture_error(e, context="api_followup")
        try:
            append_log("followup_crash", {"error": str(e)})
        except Exception:
            pass
        r = jsonify({"ok": False, "error": "Request failed. Please try again."})
        r.headers["Content-Type"] = "application/json"
        return r, 500

def _api_followup_impl(data):
    name = (data.get("name") or "").strip()
    msg = (data.get("message") or "").strip()
    file_ids = data.get("file_ids") or []
    lighting_mode = bool(data.get("lighting_mode"))

    # ── Visual save shortcut ─────────────────────────────────────────────────
    # When the frontend generates an animation it calls /api/followup with
    # save_visual=True and the finished HTML so we can persist it in the thread.
    # We write it and return immediately — no LLM call needed.
    if data.get("save_visual") and data.get("visual_html"):
        try:
            uname = _get_session_username()
            visual_html = (data.get("visual_html") or "").strip()
            user_msg    = (data.get("user_msg") or msg or "Visual request").strip()
            if name and visual_html:
                reg = load_registry(uname)
                installed = reg.get("installed") or {}
                name = _resolve_teammate_name(name, installed)
                if name in installed:
                    thread = load_thread(name, uname)
                    thread = thread[-14:] if len(thread) > 14 else thread
                    new_thread = thread + [
                        {"role": "user",      "content": user_msg},
                        {"role": "assistant", "content": visual_html},
                    ]
                    save_thread(name, new_thread, uname)
            return jsonify({"ok": True, "saved": True})
        except Exception as _ve:
            return jsonify({"ok": False, "error": str(_ve)}), 500
    # ────────────────────────────────────────────────────────────────────────

    # Auto-enable lighting_mode for explicit web search requests
    _msg_lower = (msg or "").strip().lower()
    if _msg_lower.startswith("search the web") or _msg_lower.startswith("search the internet"):
        lighting_mode = True

    if not name or not msg:
        return jsonify({"ok": False, "error": "Missing name or message"}), 400

    reg = load_registry(_get_session_username())
    installed = reg["installed"]
    name = _resolve_teammate_name(name, installed)
    if name not in installed:
        return jsonify({"ok": False, "error": "Teammate not installed"}), 400

    msg2, attach_meta, vision_images = build_prompt_with_attachments(msg, file_ids)
    # Inject URL content if the message contains links
    try:
        msg2 = _inject_url_content(msg2)
    except Exception:
        pass

    defn = installed[name]

    try:
        uname = _get_session_username()
    except Exception:
        uname = "anon"

    full_thread = load_thread(name, uname)

    # Auto re-attach last uploaded image when no new files but image was previously sent —
    # only if that upload happened recently, otherwise an old photo would be silently
    # re-sent as vision context to every future message forever.
    if not vision_images and not file_ids:
        try:
            _img_state = load_image_state(name, uname)
            _last_upload_id = (_img_state.get("last_uploaded_image_id") or "").strip()
            _last_upload_turn = _img_state.get("last_uploaded_turn") or 0
            if _last_upload_id and (len(full_thread) - _last_upload_turn) <= 6:
                _last_rec = get_upload_record(_last_upload_id)
                if _last_rec and _is_image_record(_last_rec):
                    _raw = safe_read_binary_file(
                        UPLOADS_DIR / _last_rec.get("relpath", ""),
                        MAX_INLINE_IMAGE_BYTES
                    )
                    if _raw:
                        _du = _guess_data_url(_last_rec.get("mimetype", "image/jpeg"), _raw)
                        if _du:
                            vision_images = [{"filename": _last_rec.get("filename", "photo"), "mimetype": _last_rec.get("mimetype", "image/jpeg"), "data_url": _du}]
        except Exception:
            pass

    user_content = _build_user_content(msg2, vision_images)

    thread = _truncate_thread_with_note(full_thread, max_messages=20)

    latest_uploaded_image = bind_uploaded_images_to_teammate(name, file_ids, uname)

    # RAG: retrieve relevant chunks from indexed knowledge base (non-blocking, safe)
    rag_context = ""
    try:
        rag_context = _rag_retrieve(uname, msg, top_k=4)
    except Exception:
        rag_context = ""

    # Load long-term memory for this teammate and inject it into the system prompt
    _tm_mem = load_teammate_memory(uname, name)
    _mem_lines = []
    if _tm_mem.get("facts"):       _mem_lines.append("Facts about this user: " + " | ".join(_tm_mem["facts"][:8]))
    if _tm_mem.get("preferences"): _mem_lines.append("User preferences: " + " | ".join(_tm_mem["preferences"][:5]))
    if _tm_mem.get("open_loops"):  _mem_lines.append("Open items to follow up: " + " | ".join(_tm_mem["open_loops"][:4]))
    _mem_ctx = ("LONG-TERM MEMORY (from previous sessions):\n" + "\n".join(_mem_lines)) if _mem_lines else ""

    # Determine image context BEFORE building the system prompt, so the prompt can
    # accurately tell the model whether this message will actually trigger image
    # generation — otherwise the model can promise "Here it is, generating..." for
    # a message the server never routes to the image pipeline.
    _img_state_check = load_image_state(name, uname)
    _cur_img_id = (_img_state_check.get("current_image_id") or "").strip()
    _cur_img_turn = _img_state_check.get("current_image_turn") or 0
    _img_context_recent = bool(_cur_img_id) and (len(full_thread) - _cur_img_turn) <= 6
    _has_img_ctx = _img_context_recent or bool(latest_uploaded_image)
    _is_img_req = is_image_request(msg2, has_image_context=_has_img_ctx)

    sys = teammate_system_prompt(defn, lighting_mode=lighting_mode, rag_context=rag_context, memory_context=_mem_ctx, image_request_active=_is_img_req)

    if _is_img_req:
        mode = classify_image_request_mode(msg2, name, has_reference_image=bool(latest_uploaded_image), username=uname, has_recent_context=_img_context_recent)
        # Only anchor to a prior image when there's a fresh upload, or the request
        # is an actual edit/variation — a brand-new request must not inherit the
        # last generated image as its base (see streaming handler for rationale).
        if latest_uploaded_image:
            source_rec = latest_uploaded_image
        elif mode in ("edit", "variation"):
            source_rec = _latest_image_record_from_state(name, uname)
        else:
            source_rec = None
        source_file_id = (source_rec.get("id") if isinstance(source_rec, dict) else "") or ""
        job_prompt = build_image_request_prompt(msg, name, mode=mode, source_rec=source_rec, username=uname)

        # If the user prompt is vague (short follow-up like "sounds great, give me the graphic"),
        # enrich the job prompt with the last AI message from the thread — which typically contains
        # the visual plan/description Alex just described. This prevents random unrelated images.
        _is_vague = len((msg or "").strip()) < 80 or any(
            x in (msg or "").lower() for x in [
                "sounds great", "go ahead", "give me", "proceed", "do it", "make it",
                "let's do it", "ok", "okay", "yes", "sure", "perfect", "great", "looks good",
                "make the graphic", "create it", "generate it", "send it",
                "love it", "that works", "exactly", "absolutely", "yeah", "yep", "yup",
                "do that", "let's go", "go for it", "run it", "build it", "that's perfect",
                "spot on", "nailed it", "that's the one", "let's make it", "make it happen",
                "fire away", "can you do that", "please do", "i'm in", "do this",
                "sounds good", "sounds perfect", "i like it", "love that", "great plan",
            ]
        )
        if _is_vague:
            try:
                _thread_snap = load_thread(name, uname)
                # Find the last assistant message — it should contain the visual plan
                _last_ai = ""
                for _tm in reversed(_thread_snap):
                    if _tm.get("role") == "assistant":
                        _content = _tm.get("content", "")
                        if isinstance(_content, str) and len(_content) > 50:
                            _last_ai = _content[:1200]
                            break
                if _last_ai and _last_ai not in job_prompt:
                    job_prompt = f"{job_prompt}\n\nContext from previous plan:\n{_last_ai}"
            except Exception:
                pass
        # Rate limit image generation separately (expensive API calls)
        _img_rl = _check_rate_limit("image", RATE_LIMIT_IMAGE)
        if _img_rl: return _img_rl
        job_id = create_image_job(job_prompt, teammate=name, username=uname, lighting_mode=lighting_mode, mode=mode, source_file_id=source_file_id)

        mode_label = {"edit": "Editing image", "variation": "Generating variation", "new": "Generating image"}.get(mode, "Generating image")
        placeholder = f"[{mode_label}] job:{job_id}"
        new_thread = full_thread + [{"role": "user", "content": msg2}, {"role": "assistant", "content": placeholder}]
        save_thread(name, new_thread, uname)

        st0 = load_image_state(name, uname)
        st0["last_prompt"] = msg
        st0["last_mode"] = mode
        save_image_state(name, st0, uname)

        append_log("followup_image_job", {"name": name, "prompt": msg2, "job_prompt": job_prompt, "job_id": job_id, "mode": mode, "source_file_id": source_file_id})
        append_task_log("teammate_followup_image_job", {"name": name, "prompt": msg2, "job_prompt": job_prompt, "job_id": job_id, "mode": mode, "source_file_id": source_file_id}, teammate=name, status="queued")

        return jsonify({"ok": True, "name": name, "response": placeholder, "job_id": job_id, "mode": mode, "email_draft": None, "attachment_meta": attach_meta, "image_state": load_image_state(name, uname)})

    _maybe_record_image_feedback(uname, name, msg)

    # Message limit check (mirrors streaming path)
    _plan_k = _get_user_plan(uname)
    try:
        _allowed, _used, _limit, _iused, _ilimit, _own_key = _check_msg_limit(uname, _plan_k)
    except Exception as _lim_exc:
        _log("ERROR", "msg_limit check failed", error=str(_lim_exc)[:200])
        return jsonify({"ok": False, "error": "Could not verify usage — please try again in a moment."}), 503
    if not _allowed:
        _plan_nm = (PLANS.get(_plan_k) or {}).get("name", "your plan")
        return jsonify({"ok": False, "error": f"You've used all {_limit} AI Credits included with {_plan_nm} this month. Connect your own API key in ⚙️ Settings to unlock unlimited credits and all premium models — or your credits reset on the 1st.", "limit_hit": True}), 429

    msgs: List[Dict[str, Any]] = []
    msgs.extend(thread)
    msgs.append({"role": "user", "content": user_content})

    _resolved_model = _resolve_model_for_user(defn, current_user())
    # Protect platform key: restrict to gpt-4o-mini when user has no own API key
    if not _user_has_own_key(uname):
        _resolved_model = "gpt-4o-mini"
    _tool_log: List[Dict[str, Any]] = []

    # Tool calling: skip for o1/o3/o4/claude (unsupported tools param)
    _supports_tools = not any(_resolved_model.startswith(p) for p in ("o1", "o3", "o4", "claude"))
    if _supports_tools:
        try:
            text, _tool_log = call_llm_with_tools(
                sys, msgs, temperature=0.65, model=_resolved_model,
                username=uname, u=current_user() or {}, teammate=name
            )
        except Exception:
            text = call_llm(sys, msgs, temperature=0.65, model=_resolved_model)
    else:
        text = call_llm(sys, msgs, temperature=0.65, model=_resolved_model)

    _increment_msg_usage(uname)

    new_thread = full_thread + [{"role": "user", "content": msg2}, {"role": "assistant", "content": text}]
    save_thread(name, new_thread, uname)

    draft = extract_email_draft(text)

    append_log("followup", {
        "name": name,
        "message": msg,
        "message_with_attachments": msg2,
        "attachment_meta": attach_meta,
        "vision_images_count": len(vision_images),
        "framework_length": len(load_core_framework()),
        "response": text,
        "email_draft": draft,
        "tool_calls": _tool_log,
    })

    # Task log (append-only)
    append_task_log(
        "teammate_followup",
        {
            "name": name,
            "message": msg,
            "message_with_attachments": msg2,
            "attachment_meta": attach_meta,
            "vision_images_count": len(vision_images),
            "email_draft": draft,
            "tool_calls_count": len(_tool_log),
            "response_preview": (text[:800] + ("..." if len(text) > 800 else "")),
        },
        teammate=name,
        status="success"
    )
    # onboarding_first_prompt: mark after the first successful prompt is sent
    try:
        uname = _get_session_username()
        _mark_onboarding_step(uname, "first_prompt", True)
    except Exception:
        pass

    # Auto-tag active CRM contact based on this conversation (non-blocking)
    try:
        _auto_tag_active_client_async(uname, msg, text)
    except Exception:
        pass

    # Extract shared memory from DM conversations — only when content is substantial
    # (avoids firing an extra LLM call for short/trivial exchanges)
    try:
        if len(msg) > 120 and len(text) > 200:
            _extract_shared_memory_async(uname, msg, {name: text})
    except Exception:
        pass

    return jsonify({"ok": True, "name": name, "response": text, "email_draft": draft,
                    "attachment_meta": attach_meta, "tool_calls": _tool_log})


@app.get("/api/thread/<name>")
def api_thread(name: str):
    uname = _get_session_username()
    reg = load_registry(uname)
    installed = reg["installed"]
    if name not in installed:
        return jsonify({"ok": False, "error": "Teammate not installed"}), 400
    thread = load_thread(name, uname)
    # Include branch count so the UI can show a "checkpoints" indicator
    try:
        branches = _load_branches(uname, name)
        branch_count = len((branches.get("branches") or {}))
    except Exception:
        branch_count = 0
    return jsonify({
        "ok": True,
        "thread": thread,
        "image_state": load_image_state(name, uname),
        "branch_count": branch_count,
        "has_branches": branch_count > 0,
    })

@app.post("/api/onboarding/first_ai_interaction")
def api_onboarding_first_interaction() -> Any:
    """Called after the very first AI response — marks the aha moment reached."""
    u = current_user()
    if not u: return jsonify({"ok": False}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    users_data = load_users()
    user_rec = (users_data.get("users") or {}).get(uname)
    if user_rec and not user_rec.get("first_ai_interaction_at"):
        user_rec["first_ai_interaction_at"] = now_iso()
        users_data["users"][uname] = user_rec
        save_users(users_data)
        _award_points(uname, "First AI interaction", 25)
    return jsonify({"ok": True})

@app.post("/api/thread/<name>/clear")
def api_thread_clear(name: str) -> Any:
    """Clear a single teammate's conversation thread."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
