@app.post("/api/thread/<name>/new_chat")
def api_thread_new_chat(name: str) -> Any:
    """Start a fresh conversation with a teammate. The current thread is
    archived as a restorable snapshot (not deleted), and this teammate's
    image-context pointers/history are reset so the new chat doesn't anchor
    to images from the old conversation. Long-term teammate memory
    (facts/preferences/open loops) is left untouched."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    reg = load_registry(uname)
    if name not in reg.get("installed", {}):
        return jsonify({"ok": False, "error": "Teammate not installed"}), 400

    thread = load_thread(name, uname)
    archived = False
    if thread:
        branch_id = uuid.uuid4().hex[:12]
        label = "Auto-saved before new chat — " + now_iso()[:16].replace("T", " ")
        data = _load_branches(uname, name)
        data.setdefault("branches", {})[branch_id] = {
            "id": branch_id, "label": label, "created_at": now_iso(),
            "msg_count": len(thread), "thread": thread,
        }
        brs = data["branches"]
        if len(brs) > 20:
            for old in sorted(brs, key=lambda k: brs[k].get("created_at", ""))[:-20]:
                del brs[old]
        _save_branches(uname, name, data)
        archived = True

    save_thread(name, [], uname)
    save_image_state(name, {
        "current_image_id": "", "current_image_url": "",
        "approved_image_id": "", "approved_image_url": "",
        "last_uploaded_image_id": "", "last_uploaded_image_url": "",
        "last_prompt": "", "last_mode": "", "history": [],
    }, uname)

    append_log("thread_new_chat", {"teammate": name, "by": uname, "archived": archived})
    return jsonify({"ok": True, "teammate": name, "archived": archived})

@app.post("/api/thread/<name>/truncate")
def api_thread_truncate(name: str):
    """Truncate a thread to the first keep_count messages (used by edit/regenerate)."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u["username"]
    reg = load_registry(uname)
    if name not in reg.get("installed", {}):
        return jsonify({"ok": False, "error": "Teammate not installed"}), 400
    data = request.json or {}
    keep = max(0, int(data.get("keep_count", 0)))
    thread = load_thread(name, uname)
    save_thread(name, thread[:keep], uname)
    return jsonify({"ok": True, "kept": keep, "removed": max(0, len(thread) - keep)})

@app.post("/api/thread/<name>/inject")
def api_thread_inject(name: str):
    """Append a message directly to a teammate thread (used by Pipeline and other tools)."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u["username"]
    reg = load_registry(uname)
    if name not in reg.get("installed", {}):
        return jsonify({"ok": False, "error": "Teammate not installed"}), 400
    data = request.json or {}
    role = data.get("role", "assistant")
    if role not in ("user", "assistant"):
        role = "assistant"
    content = (data.get("content") or "").strip()
    if not content:
        return jsonify({"ok": False, "error": "No content"}), 400
    thread = load_thread(name, uname)
    thread.append({"role": role, "content": content})
    save_thread(name, thread, uname)
    return jsonify({"ok": True, "msg_count": len(thread)})

@app.get("/api/search_threads")
def api_search_threads():
    """Full-text search across all of the user's saved teammate threads — index-backed for speed."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
    q = (request.args.get("q") or "").strip().lower()
    if not q or len(q) < 2:
        return jsonify({"ok": True, "results": []})
    reg = load_registry(uname)
    installed = reg.get("installed") or {}
    try:
        idx = _build_search_index(uname, installed)
        # Look up all query words/phrases in the index
        q_words = re.findall(r'\b\w{3,}\b', q)
        bigrams = [q_words[i] + " " + q_words[i+1] for i in range(len(q_words)-1)]
        search_terms = bigrams if bigrams else q_words
        if not search_terms:
            search_terms = [q] if len(q) >= 3 else []
        # Collect hits, deduplicate by (teammate, msg_index)
        seen: set = set()
        results: List[Dict[str, Any]] = []
        for term in search_terms:
            for entry in (idx.get(term) or []):
                tm_name, role, msg_idx, snippet = entry
                key = (tm_name, msg_idx)
                if key not in seen:
                    seen.add(key)
                    results.append({"teammate": tm_name, "role": role, "snippet": snippet, "msg_index": msg_idx})
                if len(results) >= 40:
                    break
            if len(results) >= 40:
                break
        return jsonify({"ok": True, "results": results, "query": q, "indexed": True})
    except Exception:
        # Fallback to linear scan if index fails
        results = []
        for tm_name in installed:
            thread = load_thread(tm_name, uname)
            for i, m in enumerate(thread):
                content = (m.get("content") or "")
                if isinstance(content, list):
                    content = " ".join(str(c) for c in content)
                if q in content.lower():
                    results.append({"teammate": tm_name, "role": m.get("role","user"),
                                    "snippet": content[:300].replace("\n"," "), "msg_index": i})
                    if len(results) >= 40: break
            if len(results) >= 40: break
        return jsonify({"ok": True, "results": results, "query": q})


