@app.post("/api/send_email")
def api_send_email():
    _rl = _check_rate_limit("email", RATE_LIMIT_EMAIL)
    if _rl: return _rl
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    data = request.get_json(force=True) or {}
    to_addr = (data.get("to") or "").strip()
    cc_addr = (data.get("cc") or "").strip()
    subject = (data.get("subject") or "").strip()
    body = (data.get("body") or "").strip()
    from_teammate = (data.get("from_teammate") or "").strip()

    if not to_addr or not subject or not body:
        return jsonify({"ok": False, "error": "Missing to, subject, or body"}), 400
    if not EMAIL_RE.match(to_addr):
        return jsonify({"ok": False, "error": "Invalid recipient email"}), 400
    if cc_addr:
        for addr in [a.strip() for a in cc_addr.split(",") if a.strip()]:
            if not EMAIL_RE.match(addr):
                return jsonify({"ok": False, "error": f"Invalid Cc email: {addr}"}), 400

    try:
        attachments = _resolve_email_attachments(u, data.get("attachments") or [])
    except ValueError as ve:
        return jsonify({"ok": False, "error": str(ve)}), 400

    # Prefer Gmail OAuth (Option C). If not connected, fall back to SMTP if configured.
    cap = _email_capability_for_user(u)

    try:
        if cap["gmail_connected"]:
            access_token, reason = _gmail_creds_for_user(u)
            if not access_token:
                return jsonify({"ok": False, "error": reason}), 400
            _gmail_send_message(access_token, to_addr=to_addr, cc_addr=cc_addr, subject=subject, body=body, from_name=_user_smtp_settings(u).get("from_name", ""), attachments=attachments)
            provider = "gmail_oauth"
        else:
            ready, reason = smtp_ready_for_user(u)
            if not ready:
                return jsonify({
                    "ok": False,
                    "error": reason,
                    "hint": "Connect Gmail in Settings to enable email sending."
                }), 400

            s = _user_smtp_settings(u)
            host = s["host"]
            port = s["port"]
            user = s["user"] or SMTP_USER
            password = s["pass"] or SMTP_PASS
            from_name = s["from_name"]
            if not user or not password:
                return jsonify({"ok": False, "error": "Missing SMTP credentials"}), 400
            send_email_smtp_with_creds(
                to_addr=to_addr,
                cc_addr=cc_addr,
                subject=subject,
                body=body,
                host=host,
                port=port,
                user=user,
                password=password,
                from_name=from_name,
                attachments=attachments
            )
            provider = "smtp"
    except Exception as e:
        append_log("email_error", {"to": to_addr, "subject": subject, "from_teammate": from_teammate, "error": str(e)})

        append_task_log(
            "send_email",
            {
                "to": to_addr,
                "subject": subject,
                "from_teammate": from_teammate,
                "provider": cap,
                "error": str(e),
            },
            teammate=from_teammate or "",
            status="failed"
        )

        return jsonify({"ok": False, "error": f"Email send failed: {e}"}), 500

    append_log("email_sent", {"to": to_addr, "subject": subject, "from_teammate": from_teammate, "provider": provider, "sent_at": now_iso()})

    append_task_log(
        "send_email",
        {
            "to": to_addr,
            "subject": subject,
            "from_teammate": from_teammate,
            "provider": provider,
            "sent_at": now_iso(),
        },
        teammate=from_teammate or "",
        status="success"
    )

    return jsonify({"ok": True, "provider": provider})




