@app.get("/gmail/callback")
def gmail_callback():
    u = current_user()
    if not u:
        return redirect("/login")
    ok, reason = _google_oauth_ready()
    if not ok:
        return make_response(f"Gmail OAuth not ready: {reason}", 400)

    state = request.args.get("state", "")
    # Primary check: session-based state (works when cookies persist across redirect)
    # Fallback: file-based store (works on hosted platforms where session cookies can be lost)
    state_ok = _oauth_state_matches("gmail_oauth_states", state)
    if not state_ok:
        try:
            rec = _consume_oauth_state(state)
            if rec:
                state_ok = True
        except Exception:
            pass
    if not state_ok:
        return make_response(
            "<html><body style='font-family:sans-serif;padding:40px;background:#0f172a;color:#e2e8f0'>"
            "<h2 style='color:#f87171'>Gmail Connect — State Mismatch</h2>"
            "<p>Your browser session was reset during the Google redirect. This is common on some hosting platforms.</p>"
            "<p><a href='/gmail/connect' style='color:#818cf8'>Click here to try connecting Gmail again</a> &mdash; "
            "it usually works on the second attempt.</p>"
            "<p><a href='/' style='color:#cbd5e1;font-size:13px'>Return to app</a></p>"
            "</body></html>", 400
        )
    code = request.args.get("code", "")
    if not code:
        return make_response("Missing authorization code from Google.", 400)

    token_info, err = _oauth_exchange_code(code, "/gmail/callback")
    if not token_info:
        append_log("gmail_connect_error", {"user": u.get("username", ""), "error": err, "at": now_iso()})
        return make_response(f"Failed to connect Gmail: {err}", 400)

    # Keep refresh_token if Google didn't re-send it
    old = _user_gmail_oauth(u) or {}
    if old.get("refresh_token") and not token_info.get("refresh_token"):
        token_info["refresh_token"] = old.get("refresh_token")

    _save_user_gmail_oauth(u, token_info)
    append_log("gmail_connected", {"user": u.get("username", ""), "at": now_iso()})
    # onboarding_gmail_connected: mark Gmail step after successful connect
    try:
        uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
        _mark_onboarding_step(uname, "email_connected", True)
    except Exception:
        pass


    return redirect("/#settings")



