@app.post("/api/calendar/create_event")
def api_calendar_create_event():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    access_token, reason = _calendar_creds_for_user(u)
    if not access_token:
        return jsonify({"ok": False, "error": reason}), 400
    payload = request.get_json(force=True, silent=True) or {}
    title = (payload.get("title") or payload.get("summary") or "Call").strip()
    start = (payload.get("start") or "").strip()
    end = (payload.get("end") or "").strip()
    timezone = (payload.get("timezone") or "America/New_York").strip()
    attendees = payload.get("attendees") or []
    if isinstance(attendees, str):
        attendees = [a.strip() for a in attendees.split(',') if a.strip()]
    description = (payload.get("description") or "").strip()
    location = (payload.get("location") or "").strip()
    use_meet = bool(payload.get("use_meet"))

    if not start or not end:
        return jsonify({"ok": False, "error": "Missing start/end. Provide ISO datetime strings."}), 400
    # Conflict detection — warn but allow override
    force = bool(payload.get("force"))
    if not force:
        conflicts = _calendar_check_conflicts(access_token, start, end, timezone)
        if conflicts:
            return jsonify({"ok": False, "conflict": True, "busy": conflicts,
                            "error": f"You already have {len(conflicts)} event(s) in that time slot. Pass force=true to book anyway."}), 409
    try:
        created = _calendar_create_event(access_token, title=title, start_iso=start, end_iso=end, timezone=timezone, attendees=attendees, description=description, location=location, use_meet=use_meet)
        append_log("calendar_event_created", {"user": u.get("username", ""), "title": title, "start": start, "end": end, "at": now_iso()})
        _award_points(u.get("username",""), "Booked a calendar event", 15)
        return jsonify({"ok": True, "event": created})
    except Exception as e:
        append_log("calendar_event_error", {"user": u.get("username", ""), "error": str(e), "at": now_iso()})
        return jsonify({"ok": False, "error": str(e)}), 500
@app.post("/api/calendar/move_event")
def api_calendar_move_event():
    """Move an existing Google Calendar event to a new time/date without creating a duplicate."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    access_token, reason = _calendar_creds_for_user(u)
    if not access_token:
        return jsonify({"ok": False, "error": reason}), 400
    payload = request.get_json(force=True, silent=True) or {}
    event_id   = (payload.get("event_id") or "").strip()
    start      = (payload.get("start") or "").strip()
    end        = (payload.get("end")   or "").strip()
    timezone   = (payload.get("timezone") or "America/New_York").strip()
    send_upd   = "all" if payload.get("resend") else "none"
    calendar_id = (payload.get("calendar_id") or "primary").strip()
    if not event_id or not start or not end:
        return jsonify({"ok": False, "error": "Missing event_id, start, or end"}), 400
    try:
        # Build patch body — also accept title/description/attendees/location updates
        patch_body: Dict[str, Any] = {
            "start": {"dateTime": start, "timeZone": timezone},
            "end":   {"dateTime": end,   "timeZone": timezone},
        }
        if payload.get("summary"):     patch_body["summary"]     = payload["summary"]
        if payload.get("description"): patch_body["description"] = payload["description"]
        if payload.get("location"):    patch_body["location"]    = payload["location"]
        if payload.get("attendees"):   patch_body["attendees"]   = [{"email": e} for e in payload["attendees"]]
        r2 = requests.patch(
            f"https://www.googleapis.com/calendar/v3/calendars/{calendar_id}/events/{event_id}",
            headers={"Authorization": f"Bearer {access_token}", "Content-Type": "application/json"},
            json=patch_body, params={"sendUpdates": send_upd}, timeout=20
        )
        updated = r2.json() if r2.status_code < 300 else None
        if not updated:
            updated = _calendar_move_event(access_token, event_id=event_id,
                                           new_start_iso=start, new_end_iso=end,
                                           timezone=timezone, send_updates=send_upd)
        append_log("calendar_event_moved", {"user": u.get("username",""), "event_id": event_id,
                                             "start": start, "at": now_iso()})
        return jsonify({"ok": True, "event": updated})
    except Exception as e:
        _capture_error(e, context="calendar_move_event")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.post("/api/calendar/delete_event")
def api_calendar_delete_event():
    """Delete a Google Calendar event by event_id."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    access_token, reason = _calendar_creds_for_user(u)
    if not access_token:
        return jsonify({"ok": False, "error": reason}), 400
    payload     = request.get_json(force=True, silent=True) or {}
    event_id    = (payload.get("event_id") or "").strip()
    calendar_id = (payload.get("calendar_id") or "primary").strip()
    if not event_id:
        return jsonify({"ok": False, "error": "Missing event_id"}), 400
    try:
        _req = requests
        r = _req.delete(
            f"https://www.googleapis.com/calendar/v3/calendars/{calendar_id}/events/{event_id}",
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=20,
        )
        if r.status_code in (200, 204):
            append_log("calendar_event_deleted", {"user": u.get("username",""), "event_id": event_id, "at": now_iso()})
            return jsonify({"ok": True})
        _capture_error(Exception(f"Calendar delete {r.status_code}: {r.text}"), context="calendar_delete_event")
        return jsonify({"ok": False, "error": f"Google Calendar returned {r.status_code}. Please try again."}), 400
    except Exception as e:
        _capture_error(e, context="calendar_delete_event")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.get("/api/calendar/events")
def api_calendar_events():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    access_token, reason = _calendar_creds_for_user(u)
    if not access_token:
        return jsonify({"ok": False, "error": reason}), 400

    time_min = (request.args.get("time_min") or "").strip()
    time_max = (request.args.get("time_max") or "").strip()
    timezone = (request.args.get("timezone") or "America/New_York").strip()
    max_results = int((request.args.get("max_results") or "250").strip() or "250")
    max_results = max(1, min(max_results, 1200))

    if not time_min or not time_max:
        return jsonify({"ok": False, "error": "Missing time_min/time_max"}), 400
    try:
        events = _calendar_list_events(access_token, time_min=time_min, time_max=time_max, timezone=timezone, max_results=max_results)
        return jsonify({"ok": True, "events": events, "truncated": len(events) >= max_results})
    except Exception as e:
        _capture_error(e, context="calendar_list_events")
        return jsonify({"ok": False, "error": str(e)}), 500


