@app.post("/api/cal/tasks")
def api_cal_tasks_create():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    payload = request.get_json(force=True, silent=True) or {}
    recur_days_raw = payload.get("recur_days") or []
    recur_days = [int(d) for d in recur_days_raw if str(d).isdigit() or isinstance(d, int)] if isinstance(recur_days_raw, list) else []
    task: Dict[str, Any] = {
        "id": str(uuid.uuid4()),
        "title": (payload.get("title") or "Untitled task").strip(),
        "date": (payload.get("date") or "").strip(),
        "start": (payload.get("start") or "09:00").strip(),
        "duration": int(payload.get("duration") or 30),
        "priority": (payload.get("priority") or "high").strip(),
        "description": (payload.get("description") or "").strip(),
        "recurring": (payload.get("recurring") or "none").strip(),
        "recur_days": recur_days,
        "on_complete_teammate": (payload.get("on_complete_teammate") or "").strip(),
        "on_complete_client_email": (payload.get("on_complete_client_email") or "").strip(),
        "on_complete_client_name": (payload.get("on_complete_client_name") or "").strip(),
        "done": False,
        "completed_at": None,
        "created_at": now_iso(),
    }
    tasks = _load_cal_tasks(u.get("username", ""))
    tasks.append(task)
    _save_cal_tasks(u.get("username", ""), tasks)
    return jsonify({"ok": True, "task": task})

@app.post("/api/cal/tasks/<task_id>")
def api_cal_tasks_update(task_id: str):
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    payload = request.get_json(force=True, silent=True) or {}
    tasks = _load_cal_tasks(u.get("username", ""))
    for t in tasks:
        if t.get("id") == task_id:
            for field in ("title", "date", "start", "priority", "description", "recurring", "on_complete_teammate", "on_complete_client_email", "on_complete_client_name"):
                if field in payload:
                    t[field] = (payload[field] or "").strip()
            # Per-instance start time overrides for recurring tasks
            # instance_start_override: {instance_date: "HH:MM"} — only moves that specific day
            if "instance_start_override" in payload:
                iso = (payload.get("instance_date") or "").strip()
                new_time = (payload.get("instance_start_override") or "").strip()
                if iso and new_time:
                    overrides = t.get("start_overrides") or {}
                    overrides[iso] = new_time
                    t["start_overrides"] = overrides
            if "recur_days" in payload:
                rd = payload["recur_days"]
                t["recur_days"] = [int(d) for d in rd if str(d).isdigit() or isinstance(d, int)] if isinstance(rd, list) else []
            if "duration" in payload:
                t["duration"] = int(payload["duration"] or 30)
            if "done" in payload:
                instance_date = (payload.get("instance_date") or "").strip()
                is_recurring = (t.get("recurring") or "none") != "none"
                if is_recurring and instance_date:
                    # Per-date done tracking for recurring tasks
                    done_dates = set(t.get("done_dates") or [])
                    if bool(payload["done"]):
                        done_dates.add(instance_date)
                    else:
                        done_dates.discard(instance_date)
                    t["done_dates"] = sorted(done_dates)
                    # Keep global done=False so other instances aren't affected
                    t["done"] = False
                    t["completed_at"] = None
                else:
                    was_done = t.get("done", False)
                    t["done"] = bool(payload["done"])
                    if t["done"] and not was_done:
                        t["completed_at"] = now_iso()
                    elif not t["done"]:
                        t["completed_at"] = None
            _save_cal_tasks(u.get("username", ""), tasks)
            return jsonify({"ok": True, "task": t})
    return jsonify({"ok": False, "error": "Task not found"}), 404


@app.post("/api/cal/tasks/<task_id>/complete_action")
def api_cal_task_complete_action(task_id: str):
    """Have the assigned teammate draft a completion email — returned for user approval, never auto-sent.
    Works for both local tasks (looked up by task_id) and Google Calendar events (fields passed inline)."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    payload = request.get_json(silent=True) or {}

    # Try to load from local task store first; fall back to inline fields from the request
    tasks = _load_cal_tasks(u.get("username", ""))
    task = next((t for t in tasks if t.get("id") == task_id), None)

    if task:
        teammate_name = (task.get("on_complete_teammate") or "").strip()
        client_email  = (task.get("on_complete_client_email") or "").strip()
        client_name   = (task.get("on_complete_client_name") or "").strip()
        task_title    = task.get("title", "Untitled task")
        # Prefer the live description sent from the frontend (may include unsaved edits)
        # over the stale version on disk
        task_desc     = (payload.get("task_description") or task.get("description") or task.get("notes") or "").strip()
        task_notes    = (payload.get("task_notes") or task.get("notes") or "").strip()
        if task_notes and task_notes not in task_desc:
            task_desc = (task_desc + "\n" + task_notes).strip()
        task_date     = task.get("date", "")
    else:
        # Google Calendar event — use inline fields sent from frontend
        teammate_name = (payload.get("on_complete_teammate") or "").strip()
        client_email  = (payload.get("on_complete_client_email") or "").strip()
        client_name   = (payload.get("on_complete_client_name") or "").strip()
        task_title    = (payload.get("task_title") or "Untitled event").strip()
        task_desc     = (payload.get("task_description") or "").strip()
        task_notes    = (payload.get("task_notes") or "").strip()
        if task_notes and task_notes not in task_desc:
            task_desc = (task_desc + "\n" + task_notes).strip()
        task_date     = (payload.get("task_date") or "").strip()

    if not teammate_name:
        return jsonify({"ok": False, "error": "No teammate configured — open the task panel and assign a teammate in the Email on Complete section."}), 400

    # voice: "operator" = written in first person as the operator, "teammate" = teammate introduces themselves
    voice = payload.get("voice", "teammate")

    reg = load_registry(_get_session_username())
    defn = (reg.get("installed") or {}).get(teammate_name)
    if not defn:
        return jsonify({"ok": False, "error": f"Teammate '{teammate_name}' not found. Make sure they are installed at the round table."}), 404

    # Load operator profile for name
    try:
        _op_user = (u.get("username") if isinstance(u, dict) else None) or "anon"
        _op = _load_operator_profile(_op_user)
        operator_name = (_op.get("display_name") or "").strip() or "the team"
        business_name = (_op.get("business") or "").strip()
    except Exception:
        operator_name = "the team"
        business_name = ""

    client_ref = client_name if client_name else (client_email if client_email else "the client")
    to_line = f"to {client_ref} (email: {client_email})" if client_email else f"to {client_ref}"

    # Build the richest possible context block from ALL available task fields.
    # Even if the user left description blank, we can still give the AI the
    # task title, date, client name and any notes — enough to write a real email.
    context_parts = []
    if task_title:
        context_parts.append(f"Task: {task_title}")
    if task_date:
        context_parts.append(f"Date: {task_date}")
    if client_name:
        context_parts.append(f"Client: {client_name}")
    if task_desc:
        context_parts.append(f"Details / activities completed:\n{task_desc}")
    else:
        context_parts.append(
            f"No detailed notes were provided. Write a warm, professional completion "
            f"email based on the task title above. Reference what the task was about "
            f"and confirm it has been completed successfully."
        )

    context_block = "\n".join(context_parts)
    detail_instruction = (
        f"\n\nTASK CONTEXT — use ALL of this when writing the email:\n"
        f"{'='*40}\n"
        f"{context_block}\n"
        f"{'='*40}\n\n"
        f"IMPORTANT: Your email MUST reference the specific task name '{task_title}' and "
        f"confirm it is done. If activities/details are listed above, mention them "
        f"specifically. Never write a vague 'just checking in' style email. "
        f"This is a task completion notification — be specific and professional."
    )

    if voice == "operator":
        sign_off_name = operator_name
        prompt = (
            f"The task '{task_title}' has just been marked complete"
            + (f" (date: {task_date})" if task_date else "")
            + f"."
            + detail_instruction
            + f"Write a professional, warm email from {operator_name} "
            + (f"at {business_name} " if business_name else "")
            + f"{to_line} reporting on what was done. "
            + f"Write in first person as {operator_name}. Address the client as '{client_ref}'. "
            + f"Sign off using exactly this closing — do not change it:\nBest,\n{sign_off_name}"
        )
    else:
        teammate_display = defn.get("name", teammate_name)
        sign_off_name = teammate_display
        brand_phrases = [
            f"from Simply Agentic AI",
            f"here at Simply Agentic AI",
            f"with Simply Agentic AI",
            f"over at Simply Agentic AI",
            f"at Simply Agentic AI",
        ]
        import hashlib as _hsh
        _phrase = brand_phrases[int(_hsh.md5((task_title + teammate_display).encode()).hexdigest(), 16) % len(brand_phrases)]
        prompt = (
            f"The task '{task_title}' has just been marked complete"
            + (f" (date: {task_date})" if task_date else "")
            + f"."
            + detail_instruction
            + f"Write a professional, warm email from {teammate_display} ({_phrase}) "
            + f"{to_line} reporting on what was done. "
            + f"In the opening, introduce yourself naturally — for example: 'I'm {teammate_display} {_phrase}.' "
            + f"Address the client as '{client_ref}'. "
            + f"Mention Simply Agentic AI naturally in the opening. "
            + f"Sign off using exactly this closing — do not change it:\nBest,\n{sign_off_name}"
        )

    prompt += (
        "Use EXACTLY this format and nothing else:\n"
        "```email\n"
        "To: " + (client_email or "[client email]") + "\n"
        "Subject: <subject line here>\n"
        "Body: <first line of body>\n"
        "<rest of body>\n"
        "```\n"
        "CRITICAL: Do NOT write the word 'email' anywhere in the body. "
        "Do NOT include 'To:', 'From:', or header labels inside the Body. "
        "Do NOT end with ``` or any backticks. "
        "Do NOT change the sign-off — use the exact name provided, no placeholder text like '[Name]' or 'Your Name'. "
        "Start the Body directly with the greeting."
    )

    try:
        oai = _get_openai_client_for_username(u.get("username",""))
        teammate_display = defn.get("name", teammate_name)
        # Use a focused, permissive system prompt for email drafting.
        # Do NOT use teammate_system_prompt here — the full framework's "pause if unclear"
        # rules cause the model to refuse legitimate email draft requests.
        email_sys_prompt = (
            f"You are {teammate_display}, a professional AI business assistant. "
            f"Your sole task right now is to write a task completion notification email. "
            f"This is a 100% legitimate, pre-authorised business communication. "
            f"You MUST write the email — refusing, asking for clarification, or adding "
            f"caveats is not permitted. Use the task context provided. "
            f"If details are sparse, write a warm, professional completion email based on "
            f"the task title — that is always enough to write a good email. "
            f"Never say you cannot help, never ask questions, never hedge. Just write the email. "
            f"No em dashes. Use the exact format requested."
        )
        resp = oai.chat.completions.create(
            model=(defn.get("preferred_model") or MODEL),
            messages=[
                {"role": "system", "content": email_sys_prompt},
                {"role": "user",   "content": prompt},
            ],
            temperature=0.65,
            max_tokens=900,
            timeout=45,
        )
        raw = (resp.choices[0].message.content or "").strip()
    except Exception as e:
        _capture_error(e, context="teammate_email_draft")
        return jsonify({"ok": False, "error": f"Teammate AI error: {e}"}), 500

    # Try structured extract first (uses the ```email block)
    draft = extract_email_draft(raw)
    if draft and draft.get("body"):
        subject = draft.get("subject") or f"Task Complete: {task_title}"
        body = draft.get("body", "")
    else:
        # Fallback: parse subject + body manually
        lines = raw.splitlines()
        subject = f"Task Complete: {task_title}"
        body_lines = []
        found_subject = False
        for ln in lines:
            stripped = ln.strip()
            if not found_subject and stripped.lower().startswith("subject:"):
                subject = stripped[8:].strip()
                found_subject = True
            else:
                body_lines.append(ln)
        body = "\n".join(body_lines).strip()
        if not body:
            body = raw

    # Clean up any stray artifacts the model may have added
    # Strip leading "email" line (case-insensitive, possibly on its own line)
    body = re.sub(r'(?i)^\s*email\s*\n', '', body)
    body = re.sub(r'(?i)^email\s+to:.*\n?', '', body)
    # Strip trailing ``` or ```email
    body = re.sub(r'\s*```\s*$', '', body).strip()
    body = re.sub(r'\s*```email\s*$', '', body).strip()
    # Strip any stray To:/From: lines that leaked into the body
    body = re.sub(r'(?im)^(To|From|CC|BCC)\s*:.*(\r?\n|$)', '', body).strip()

    # Return draft for user approval — do NOT send automatically
    append_log("task_complete_email_drafted", {
        "task_id": task_id, "task_title": task_title,
        "teammate": teammate_name, "to": client_email,
        "client_name": client_name, "voice": voice, "at": now_iso()
    })
    return jsonify({"ok": True, "draft": True, "subject": subject, "body": body,
                    "to": client_email, "teammate": teammate_name})

@app.delete("/api/cal/tasks/<task_id>")
def api_cal_tasks_delete(task_id: str):
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    tasks = _load_cal_tasks(u.get("username", ""))
    tasks = [t for t in tasks if t.get("id") != task_id]
    _save_cal_tasks(u.get("username", ""), tasks)
    return jsonify({"ok": True})

