@app.get("/api/operator_profile")
def api_operator_profile_get():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    prof = _load_operator_profile(uname)
    return jsonify({"ok": True, "profile": prof})

@app.post("/api/operator_profile")
def api_operator_profile_set():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    prof = _load_operator_profile(uname)
    # only update known keys (additive safety)
    for k in ["display_name","business","offers","audience","goals","notes"]:
        if k in payload:
            prof[k] = (payload.get(k) or "")
    _save_operator_profile(uname, prof)
    # Invalidate sys-ctx cache so next LLM call sees the updated profile
    try:
        _invalidate_sys_ctx_cache(uname)
    except Exception:
        pass
    # onboarding_operator_profile: mark Operator Profile step when profile is saved with any meaningful content
    try:
        uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
        op = _load_operator_profile(uname) or {}
        meaningful = ["business", "offers", "audience", "goals", "notes"]
        ok = False
        for k in meaningful:
            if (op.get(k) or "").strip():
                ok = True
                break
        if ok:
            _mark_onboarding_step(uname, "operator_profile", True)
    except Exception:
        pass

    # Re-index the operator's business context into RAG so teammates stay current
    # (background thread — never blocks the save; safe no-op without an API key).
    try:
        threading.Thread(target=_rag_autoingest_operator, args=(uname,), daemon=True).start()
    except Exception:
        pass

    return jsonify({"ok": True, "profile": prof})



