# ACCOUNT DELETION (GDPR / user self-service)
# =========================

@app.post("/api/account/delete")
def api_account_delete():
    """Permanently delete the current user's account and all their data."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    uname = (u.get("username") if isinstance(u, dict) else None) or ""
    if not uname:
        return jsonify({"ok": False, "error": "Could not determine username"}), 400

    if _is_admin_user(u):
        return jsonify({"ok": False, "error": "Admin accounts cannot be self-deleted. Transfer admin rights first."}), 403

    # Require password confirmation
    body = request.get_json(silent=True) or {}
    pw_confirm = (body.get("password") or "").strip()
    if not pw_confirm:
        return jsonify({"ok": False, "error": "Password confirmation required"}), 400
    if not check_password_hash(u.get("password_hash", ""), pw_confirm):
        return jsonify({"ok": False, "error": "Incorrect password"}), 403

    safe = _safe_name(uname)
    errors = []

    # 1. Remove user from the users store (explicit single-row delete).
    try:
        delete_user(uname)
    except Exception as e:
        errors.append(f"users: {e}")

    # 2. Cancel Stripe subscription and release seat
    try:
        seats_data = _load_seats()
        for code, seat in (seats_data.get("seats") or {}).items():
            if seat.get("claimed_by") == uname:
                cust_id = seat.get("stripe_customer_id", "")
                if cust_id and STRIPE_SECRET_KEY:
                    st, sd = _stripe_api("GET", "/subscriptions", {"customer": cust_id, "status": "active", "limit": "5"})
                    if st == 200:
                        for sub in (sd.get("data") or []):
                            _stripe_api("POST", f"/subscriptions/{sub['id']}/cancel", {})
                seat["claimed_by"] = None
                seat["status"]     = "inactive"
                seat["deleted_at"] = now_iso()
        _save_seats(seats_data)
    except Exception as e:
        errors.append(f"stripe/seat: {e}")

    # 3. Delete per-user data directories
    for dirpath in [
        USER_TEAMMATES_DIR / f"{safe}.json",
        USER_THREADS_DIR / safe,
        USER_IMG_STATE_DIR / safe,
        ACTION_STACKS_DIR / safe,
        ACTION_STACK_RUNS_DIR / safe,
        ACTION_STACK_MEMORY_DIR / safe,
        ACTION_STACK_SCHEDULES_DIR / safe,
        ONBOARDING_DIR / safe,
        TASK_LOG_DIR / f"{safe}.jsonl",
        DATA / "clients" / f"{safe}.json",
        DATA / "operator_profile" / f"{safe}.json",
    ]:
        try:
            p = Path(dirpath)
            if p.is_dir():
                shutil.rmtree(p, ignore_errors=True)
            elif p.exists():
                p.unlink(missing_ok=True)
        except Exception as e:
            errors.append(f"{dirpath}: {e}")

    # 4. Remove uploaded files owned by this user
    try:
        idx = load_json(UPLOAD_INDEX_PATH, {})
        kept = []
        for rec in (idx.get("files") or []):
            if rec.get("owner") == uname:
                fp = UPLOADS_DIR / rec.get("path", "")
                try:
                    Path(fp).unlink(missing_ok=True)
                except Exception:
                    pass
            else:
                kept.append(rec)
        idx["files"] = kept
        save_json(UPLOAD_INDEX_PATH, idx)
    except Exception as e:
        errors.append(f"uploads: {e}")

    # 5. Clear their session
    try:
        session.clear()
    except Exception:
        pass

    if errors:
        append_log("account_delete_partial", {"username": uname, "errors": errors})

    _audit_log("account_deleted", {"errors": errors}, username=uname)
    return jsonify({"ok": True, "message": "Account and data deleted successfully.", "errors": errors})


# Precompiled once at startup — render_template_string() would otherwise
# re-lex/parse this multi-thousand-line template on every single request
# (including health checks), which can blow past Render's 5s health check
# timeout under cold-start CPU throttling with a single gunicorn worker.

