@app.post("/api/crm/clients")
def api_crm_clients_create():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    name = (payload.get("name") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "Name is required"}), 400
    val_err = _validate_crm_client_fields(payload)
    if val_err:
        return jsonify({"ok": False, "error": val_err}), 400
    crm = _crm_load(uname)

    # Plan-based contact limit
    plan_key  = _get_user_plan(uname)
    plan_info = PLANS.get(_normalize_plan_key(plan_key)) or PLANS["solo"]
    max_contacts = plan_info.get("crm_contacts")  # None = unlimited
    if max_contacts is not None:
        current_count = len(crm.get("clients") or {})
        if current_count >= max_contacts:
            plan_name = plan_info.get("name", "your plan")
            upgrade_to = "Teams ($127/mo)" if _normalize_plan_key(plan_key) in ("solo", "founder") else "contact support"
            return jsonify({"ok": False, "error": f"You've reached the {max_contacts} contact limit on {plan_name}. Upgrade to {upgrade_to} to add more contacts. <a href='/stripe/manage' style='color:#c4b5fd;'>Manage plan →</a>"}), 403

    cid = _crm_new_id("c")
    now = now_iso()
    tags_in = payload.get("tags") or []
    if isinstance(tags_in, str):
        tags = [t.strip() for t in tags_in.split(",") if t.strip()]
    elif isinstance(tags_in, list):
        tags = [str(t).strip() for t in tags_in if str(t).strip()]
    else:
        tags = []
    stage = (payload.get("pipeline_stage") or "Lead").strip()
    if stage not in (crm.get("pipeline",{}).get("stages") or []):
        stage = "Lead"
    client = {
        "id": cid,
        "name": name,
        "company": (payload.get("company") or "").strip(),
        "email": (payload.get("email") or "").strip(),
        "phone": (payload.get("phone") or "").strip(),
        "tags": tags,
        "status": (payload.get("status") or "lead").strip(),
        "pipeline_stage": stage,
        "last_contact": (payload.get("last_contact") or "").strip(),
        "next_followup": (payload.get("next_followup") or "").strip(),
        "notes": (payload.get("notes") or "").strip(),
        "last_summary": (payload.get("last_summary") or "").strip(),
        "deal_value": float(payload.get("deal_value") or 0),
        "custom_fields": payload.get("custom_fields") if isinstance(payload.get("custom_fields"), dict) else {},
        "created_at": now,
        "updated_at": now,
    }
    try:
        client = _crm_enrich_client_record(client)
    except Exception:
        pass  # enrichment is best-effort
    try:
        client = _crm_apply_pipeline_rules(uname, client)
    except Exception:
        pass  # rules are best-effort
    try:
        crm["clients"][cid] = client
        _crm_save(uname, crm)
    except Exception as _save_err:
        return jsonify({"ok": False, "error": f"Storage error: {_save_err}"}), 500
    try:
        _award_points(uname, "Added a CRM contact", 5)
        _mark_onboarding_step(uname, "crm_contact", True)
    except Exception:
        pass
    return jsonify({"ok": True, "client": client})

@app.post("/api/crm/clients/<client_id>")
def api_crm_clients_update(client_id: str):
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    val_err = _validate_crm_client_fields(payload)
    if val_err:
        return jsonify({"ok": False, "error": val_err}), 400
    crm = _crm_load(uname)
    clients = crm.get("clients") or {}
    if client_id not in clients or not isinstance(clients[client_id], dict):
        return jsonify({"ok": False, "error": "Client not found"}), 404
    c = clients[client_id]
    for k in ["name","company","email","phone","status","last_contact","next_followup","notes","last_summary"]:
        if k in payload:
            c[k] = (payload.get(k) or "").strip()
    if "deal_value" in payload:
        c["deal_value"] = float(payload.get("deal_value") or 0)
    if "pipeline_stage" in payload:
        stage = (payload.get("pipeline_stage") or "").strip()
        valid_stages = crm.get("pipeline",{}).get("stages") or []
        if stage and stage not in valid_stages:
            return jsonify({"ok": False, "error": f"Invalid stage '{stage}'. Valid stages: {', '.join(valid_stages)}"}), 400
        if stage:
            old_stage = c.get("pipeline_stage", "")
            c["pipeline_stage"] = stage
            if stage != old_stage and old_stage:
                _award_points(uname, f"Moved contact to {stage}", 10)
                _crm_activity_append(uname, client_id, "stage_change", f"{old_stage} → {stage}")
    if "tags" in payload:
        tags_in = payload.get("tags") or []
        if isinstance(tags_in, str):
            c["tags"] = [t.strip() for t in tags_in.split(",") if t.strip()]
        elif isinstance(tags_in, list):
            c["tags"] = [str(t).strip() for t in tags_in if str(t).strip()]
    if "custom_fields" in payload and isinstance(payload.get("custom_fields"), dict):
        c["custom_fields"] = payload.get("custom_fields") or {}
    c["updated_at"] = now_iso()
    c = _crm_enrich_client_record(c)
    clients[client_id] = c
    crm["clients"] = clients
    _crm_save(uname, crm)
    if payload.get("notes") and payload["notes"].strip():
        _crm_activity_append(uname, client_id, "note", payload["notes"].strip()[:200])
    # Apply pipeline rules in background (they may invoke LLM — don't block the response)
    def _bg_rules():
        try:
            crm2 = _crm_load(uname)
            clients2 = crm2.get("clients") or {}
            if client_id in clients2:
                clients2[client_id] = _crm_apply_pipeline_rules(uname, clients2[client_id])
                crm2["clients"] = clients2
                _crm_save(uname, crm2)
        except Exception:
            pass
    threading.Thread(target=_bg_rules, daemon=True).start()
    return jsonify({"ok": True, "client": c})

