def _crm_is_blocked_domain(domain: str) -> bool:
    d = _crm_extract_domain(domain)
    if not d:
        return True
    for item in _CRM_SEARCH_BLOCKED_DOMAINS:
        if d == item or d.endswith("." + item):
            return True
    return False


def _crm_clean_phone(phone: str) -> str:
    digits = re.sub(r"\D", "", phone or "")
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) == 10:
        return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"
    return (phone or "").strip()


def _crm_extract_emails_from_text(text: str) -> List[str]:
    vals = re.findall(r"[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}", text or "", flags=re.I)
    out = []
    seen = set()
    for e in vals:
        e = e.strip(" .,;:>)]}\"'\n\r\t").lower()
        if any(x in e for x in ["example.com", ".png", ".jpg", ".jpeg", ".gif", ".webp", "sentry.io"]):
            continue
        if e not in seen:
            seen.add(e)
            out.append(e)
    return out


def _crm_extract_phones_from_text(text: str) -> List[str]:
    vals = re.findall(r"(?:\+?1[\s\-.]?)?(?:\(?\d{3}\)?[\s\-.]?)\d{3}[\s\-.]?\d{4}", text or "")
    out = []
    seen = set()
    for v in vals:
        c = _crm_clean_phone(v)
        digits = re.sub(r"\D", "", c)
        if len(digits) == 10 and c not in seen:
            seen.add(c)
            out.append(c)
    return out


def _crm_best_person_name(candidates: List[str], company: str = "") -> str:
    company_words = set(re.findall(r"[a-z]+", (company or "").lower()))
    for raw in candidates:
        val = re.sub(r"\s+", " ", (raw or "").strip(" |,-"))
        if not val:
            continue
        parts = [p for p in re.split(r"\s+", val) if p]
        if len(parts) < 2 or len(parts) > 4:
            continue
        bad = False
        clean_parts = []
        for p in parts:
            letters = re.sub(r"[^A-Za-z]", "", p)
            if not letters:
                bad = True
                break
            low = letters.lower()
            if low in _CRM_BAD_PERSON_WORDS or low in company_words:
                bad = True
                break
            if not letters[0].isupper() and not p[:1].isupper():
                bad = True
                break
            clean_parts.append(letters.capitalize())
        if bad:
            continue
        joined = " ".join(clean_parts)
        if len(joined) >= 5:
            return joined
    return ""


def _crm_guess_company(title: str, domain: str) -> str:
    title = re.sub(r"\s+", " ", (title or "").strip())
    if title:
        for piece in re.split(r"\||•|-|—|–", title):
            piece = piece.strip()
            if not piece:
                continue
            words = set(re.findall(r"[a-z]+", piece.lower()))
            if words & {"contact", "about", "search", "duckduckgo", "google", "bing"}:
                continue
            if len(piece) >= 3:
                return piece[:140]
    d = _crm_extract_domain(domain)
    if not d:
        return ""
    stem = d.split(".")[0].replace("-", " ").replace("_", " ").strip()
    return stem.title()


def _crm_fetch_text_url(url: str, timeout: int = 14) -> Tuple[str, str]:
    try:
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"}
        r = _safe_requests_get(url, headers, timeout)
        if r is None:
            return "", url
        ctype = (r.headers.get("Content-Type") or "").lower()
        if r.status_code >= 400:
            return "", r.url or url
        if "text/html" not in ctype and "application/xhtml+xml" not in ctype and ctype:
            return "", r.url or url
        return r.text or "", r.url or url
    except Exception:
        return "", url


def _crm_fetch_contact_pages(domain: str, timeout: int = 8) -> List[Tuple[str, str]]:
    """Fetch the homepage + /contact + /about for a domain in parallel.
    Capped at 4 URLs and stops after collecting 2 useful pages to limit RAM usage.
    Returns list of (html, url) for pages that responded successfully.
    """
    base = f"https://{domain}"
    candidates = [
        base,
        base + "/contact",
        base + "/about",
        base + "/contact-us",
    ]
    results: List[Tuple[str, str]] = []
    def fetch_one(u: str) -> Tuple[str, str]:
        try:
            headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"}
            r = _safe_requests_get(u, headers, timeout, max_bytes=150_000)
            if r is not None:
                ctype = (r.headers.get("Content-Type") or "").lower()
                if r.status_code < 400 and ("text/html" in ctype or not ctype):
                    return r.text or "", r.url or u
        except Exception:
            pass
        return "", u
    try:
        with ThreadPoolExecutor(max_workers=2) as ex:
            futures = {ex.submit(fetch_one, u): u for u in candidates}
            for fut in as_completed(futures, timeout=15):
                html, final_url = fut.result(timeout=0)
                if html:
                    results.append((html, final_url))
                    if len(results) >= 2:  # 2 pages is enough; stop early to save RAM
                        break
    except Exception:
        pass
    return results


def _crm_same_domain(url_a: str, url_b: str) -> bool:
    da = _crm_extract_domain(urlparse(url_a).netloc or url_a)
    db = _crm_extract_domain(urlparse(url_b).netloc or url_b)
    return bool(da and db and da == db)


def _crm_find_contact_links(html: str, base_url: str) -> Tuple[List[str], List[str]]:
    """Return (page_links, mailto_emails) found in the HTML.
    Page links: contact/about/team sub-pages worth scraping.
    Mailto emails: email addresses found directly in href="mailto:..." attributes.
    """
    page_links: List[str] = []
    mailto_emails: List[str] = []
    seen_links: set = set()
    seen_emails: set = set()
    if not html:
        return page_links, mailto_emails
    if BeautifulSoup is not None:
        try:
            soup = BeautifulSoup(html, "html.parser")
            for a in soup.find_all("a", href=True):
                href = (a.get("href") or "").strip()
                # Capture emails from mailto: links — most reliable source
                if href.lower().startswith("mailto:"):
                    email = href[7:].split("?")[0].strip().lower()
                    if email and "@" in email and email not in seen_emails:
                        # Basic validity check
                        if re.match(r"[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}", email):
                            seen_emails.add(email)
                            mailto_emails.append(email)
                    continue
                if href.lower().startswith("tel:"):
                    continue
                label = " ".join([a.get_text(" ", strip=True), href]).lower()
                if not any(k in label for k in ["contact", "about", "agent", "team", "staff", "bio", "reach", "connect", "email"]):
                    continue
                full = urljoin(base_url, href)
                if not _crm_same_domain(full, base_url):
                    continue
                if full not in seen_links:
                    seen_links.add(full)
                    page_links.append(full)
        except Exception:
            pass
    return page_links[:4], mailto_emails


def _crm_parse_page_signals(html: str, url: str, niche: str, location: str) -> Dict[str, Any]:
    title = ""
    headings = []
    visible_text = re.sub(r"<script.*?</script>|<style.*?</style>", " ", html or "", flags=re.I | re.S)
    visible_text = re.sub(r"<[^>]+>", " ", visible_text)
    visible_text = re.sub(r"\s+", " ", visible_text).strip()
    mailto_emails: List[str] = []
    if BeautifulSoup is not None and html:
        try:
            soup = BeautifulSoup(html, "html.parser")
            if soup.title and soup.title.string:
                title = soup.title.string.strip()
            if not title:
                og = soup.find("meta", attrs={"property": "og:title"}) or soup.find("meta", attrs={"name": "title"})
                if og and og.get("content"):
                    title = og.get("content").strip()
            headings = [x.get_text(" ", strip=True) for x in soup.find_all(["h1", "h2"], limit=8)]
            # Extract emails from mailto: hrefs — most reliable method
            for a in soup.find_all("a", href=True):
                href = (a.get("href") or "").strip()
                if href.lower().startswith("mailto:"):
                    email = href[7:].split("?")[0].strip().lower()
                    if email and "@" in email and re.match(r"[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}", email):
                        if not any(x in email for x in ["example.com", ".png", ".jpg"]):
                            mailto_emails.append(email)
        except Exception:
            pass
    # Also regex-scan raw HTML + visible text for any plaintext emails
    regex_emails = _crm_extract_emails_from_text((html or "") + "\n" + visible_text)
    # Merge: mailto hrefs first (most trustworthy), then regex finds
    all_emails: List[str] = []
    seen_e: set = set()
    for e in (mailto_emails + regex_emails):
        if e and e not in seen_e:
            seen_e.add(e)
            all_emails.append(e)
    phones = _crm_extract_phones_from_text((html or "") + "\n" + visible_text)
    company = _crm_guess_company(title or (headings[0] if headings else ""), url)
    person_name = _crm_best_person_name(([title] if title else []) + headings, company=company)
    text_l = (title + " " + " ".join(headings) + " " + visible_text[:5000]).lower()
    niche_hit = bool(niche and all(tok in text_l for tok in [t for t in re.findall(r"[a-z0-9]+", niche.lower())[:2]])) or any(k in text_l for k in ["realtor", "real estate", "broker", "brokerage", "homes for sale", "properties"])
    location_hit = bool(location and any(tok in text_l for tok in re.findall(r"[a-z0-9]+", location.lower())[:2]))
    return {
        "title": title,
        "headings": headings,
        "visible_text": visible_text,
        "emails": all_emails,
        "phones": phones,
        "company": company,
        "name": person_name,
        "niche_hit": bool(niche_hit),
        "location_hit": bool(location_hit),
    }


def _crm_merge_email_candidates(public_emails: List[str], name: str, domain: str) -> List[Dict[str, Any]]:
    out = []
    seen = set()
    for e in public_emails[:5]:
        if e not in seen:
            seen.add(e)
            out.append({"email": e, "confidence": 0.97, "status": "public"})
    for row in _crm_email_candidates(name, domain):
        if row.get("email") not in seen:
            seen.add(row.get("email"))
            out.append(row)
    return out[:5]


def _crm_score_candidate(candidate: Dict[str, Any], niche: str, location: str) -> int:
    score = 35
    if candidate.get("website"):
        score += 10
    if candidate.get("phone"):
        score += 18
    if candidate.get("email"):
        score += 25
    if candidate.get("linkedin"):
        score += 10
    if candidate.get("facebook"):
        score += 5
    if candidate.get("google_rating"):
        score += 8
    if candidate.get("name") and candidate.get("name") != candidate.get("company"):
        score += 12
    if candidate.get("niche_hit"):
        score += 8
    if candidate.get("location_hit"):
        score += 8
    if niche and any(tok in (candidate.get("notes") or "").lower() for tok in re.findall(r"[a-z0-9]+", niche.lower())[:2]):
        score += 5
    return max(1, min(99, score))


# ── New enrichment helpers ────────────────────────────────────────────────────

def _crm_find_linkedin(name: str, company: str, location: str) -> str:
    """Search for a LinkedIn profile/company URL. Returns URL or empty string."""
    if not name and not company:
        return ""
    query = f"{(name or company).strip()} {company.strip()} {location.strip()} LinkedIn"
    try:
        rows = _crm_ddg_search(query, max_results=6)
        for row in rows:
            url = row.get("url") or ""
            if "linkedin.com/in/" in url or "linkedin.com/company/" in url:
                # Normalise to clean profile URL
                m = re.search(r"(https?://(?:www\.)?linkedin\.com/(?:in|company)/[^/?&#\s]+)", url)
                if m:
                    return m.group(1)
    except Exception:
        pass
    return ""


def _crm_find_facebook(company: str, domain: str, html: str = "") -> str:
    """Extract a Facebook business page URL from page HTML or a targeted search."""
    # First: look in existing HTML for facebook links
    if html and BeautifulSoup is not None:
        try:
            soup = BeautifulSoup(html, "html.parser")
            for a in soup.find_all("a", href=True):
                href = (a.get("href") or "").strip()
                if "facebook.com/" in href and "/sharer" not in href and "/share" not in href:
                    m = re.search(r"(https?://(?:www\.)?facebook\.com/[^/?&#\s\"']+)", href)
                    if m:
                        pg = m.group(1)
                        # Skip generic facebook.com or login pages
                        if not re.search(r"facebook\.com/(login|sharer|share|dialog|profile\.php)", pg):
                            return pg
        except Exception:
            pass
    return ""


def _crm_extract_google_rating(snippet: str) -> Dict[str, Any]:
    """Extract Google/Yelp star rating and review count from a search snippet."""
    rating_match = re.search(r"(\d+(?:\.\d)?)\s*(?:out of 5|stars?|★|⭐)", snippet or "", re.I)
    reviews_match = re.search(r"([\d,]+)\s*(?:reviews?|ratings?)", snippet or "", re.I)
    result: Dict[str, Any] = {}
    if rating_match:
        try:
            result["google_rating"] = float(rating_match.group(1))
        except Exception:
            pass
    if reviews_match:
        try:
            result["review_count"] = int(reviews_match.group(1).replace(",", ""))
        except Exception:
            pass
    return result


def _crm_detect_business_type(html: str, name: str, company: str) -> str:
    """Return 'solo', 'team', or 'agency' based on page signals."""
    text = (html or "").lower()
    team_signals = ["our team", "meet the team", "our agents", "our staff",
                    "our associates", "our brokers", "meet our", "our office"]
    agency_signals = ["franchise", "branches", "locations", "offices nationwide",
                      "nationwide", "regional office", "corporate", "inc.", " llc", " ltd"]
    if any(s in text for s in agency_signals):
        return "agency"
    if any(s in text for s in team_signals):
        return "team"
    return "solo"


def _crm_detect_activity(html: str, snippet: str) -> str:
    """Return 'active', 'moderate', or 'dormant' based on recency signals."""
    combined = ((html or "") + " " + (snippet or "")).lower()
    current_year = datetime.utcnow().year
    recent_years = [str(current_year), str(current_year - 1)]
    if any(y in combined for y in recent_years):
        return "active"
    old_years = [str(y) for y in range(2015, current_year - 2)]
    if any(y in combined for y in old_years) and not any(y in combined for y in [str(current_year - 2)]):
        return "dormant"
    return "moderate"


def _crm_contact_confidence(email: str, email_source: str) -> str:
    """Return 'high', 'medium', or 'low' based on how the email was found."""
    if not email:
        return "none"
    if email_source == "mailto":
        return "high"
    if email_source == "snippet":
        return "high"
    if email_source == "page_text":
        return "medium"
    return "low"


def _crm_warm_reason(candidate: Dict[str, Any], niche: str, location: str) -> str:
    """Generate a one-line reason why this lead is worth contacting."""
    reasons = []
    if candidate.get("email") and candidate.get("email_source") in ("mailto", "snippet"):
        reasons.append("publicly listed email")
    if candidate.get("phone"):
        reasons.append("direct phone number")
    if candidate.get("linkedin"):
        reasons.append("active LinkedIn presence")
    if candidate.get("google_rating"):
        rating = candidate["google_rating"]
        count = candidate.get("review_count", 0)
        reasons.append(f"{rating}★ Google rating ({count} reviews)" if count else f"{rating}★ Google rating")
    if candidate.get("business_type") == "solo":
        reasons.append("solo operator — direct decision maker")
    if candidate.get("activity") == "active":
        reasons.append("recently active online")
    if not reasons:
        if candidate.get("website"):
            reasons.append("verified business website")
        else:
            reasons.append(f"found in {location or 'target area'} {niche or ''} search")
    return ", ".join(reasons[:3]).capitalize() + "."



def _crm_ddg_search(query: str, max_results: int = 12) -> List[Dict[str, str]]:
    try:
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"}
        r = requests.post("https://html.duckduckgo.com/html/", data={"q": query}, headers=headers, timeout=20)
        html = r.text or ""
    except Exception:
        return []
    out = []
    seen = set()
    if BeautifulSoup is not None and html:
        try:
            soup = BeautifulSoup(html, "html.parser")
            for result_div in soup.select("div.result, div.web-result"):
                a = result_div.select_one("a.result__a")
                if not a:
                    continue
                href = (a.get("href") or "").strip()
                title = a.get_text(" ", strip=True)
                if not href:
                    continue
                href = unquote(href)
                if href.startswith("//"):
                    href = "https:" + href
                if href.startswith("/") and "uddg=" in href:
                    m = re.search(r"uddg=([^&]+)", href)
                    if m:
                        href = unquote(m.group(1))
                domain = _crm_extract_domain(urlparse(href).netloc or href)
                if not href.startswith("http") or _crm_is_blocked_domain(domain):
                    continue
                if domain in seen:
                    continue
                seen.add(domain)
                snip_el = result_div.select_one(".result__snippet") or result_div.select_one("a.result__snippet")
                snippet = snip_el.get_text(" ", strip=True) if snip_el else ""
                row: Dict[str, str] = {"url": href, "title": title, "domain": domain, "snippet": snippet}
                snippet_emails = _crm_extract_emails_from_text(snippet)
                if snippet_emails:
                    row["email_hint"] = snippet_emails[0]
                out.append(row)
                if len(out) >= max_results:
                    break
            # Fallback: grab plain result links if structured divs not found
            if not out:
                for a in soup.select("a.result__a"):
                    href = (a.get("href") or "").strip()
                    title = a.get_text(" ", strip=True)
                    if not href:
                        continue
                    href = unquote(href)
                    if href.startswith("//"):
                        href = "https:" + href
                    if href.startswith("/") and "uddg=" in href:
                        m2 = re.search(r"uddg=([^&]+)", href)
                        if m2:
                            href = unquote(m2.group(1))
                    domain = _crm_extract_domain(urlparse(href).netloc or href)
                    if not href.startswith("http") or _crm_is_blocked_domain(domain) or domain in seen:
                        continue
                    seen.add(domain)
                    out.append({"url": href, "title": title, "domain": domain, "snippet": ""})
                    if len(out) >= max_results:
                        break
        except Exception:
            pass
    return out


def _crm_build_queries(niche: str, location: str, lead_count: int, search_mode: str) -> List[str]:
    niche = (niche or "businesses").strip()
    location = (location or "United States").strip()
    mode = (search_mode or "balanced").strip().lower()
    locations = [location]
    loc_key = location.strip().lower()
    if loc_key in _CRM_STATE_CITY_MAP:
        extra = _CRM_STATE_CITY_MAP[loc_key]
        if mode == "precision":
            locations.extend(extra[:4])
        elif mode == "broad":
            locations.extend(extra[:12])
        else:
            locations.extend(extra[:8])
    _is_realty = bool(re.search(r'real.?estate|realtor|broker|realty', niche, flags=re.I))
    templates = ['{niche} in {loc} contact', '{loc} {niche} office', '{loc} {niche} team', '{loc} {niche} website']
    if _is_realty:
        templates += ['{loc} {niche} realtor broker', '{loc} {niche} real estate agent']
    queries = []
    seen = set()
    for loc in locations:
        for tpl in templates:
            q = tpl.format(niche=niche, loc=loc).strip()
            if q.lower() not in seen:
                seen.add(q.lower())
                queries.append(q)
    max_q = 8 if mode == "precision" else (14 if mode == "balanced" else 20)
    return queries[:max_q]


def _crm_enrich_result(result: Dict[str, str], niche: str, location: str, query: str) -> Optional[Dict[str, Any]]:
    url = result.get("url") or ""
    domain = result.get("domain") or _crm_extract_domain(urlparse(url).netloc or url)
    if not url or _crm_is_blocked_domain(domain):
        return None
    hint_name    = (result.get('name_hint') or '').strip()
    hint_company = (result.get('company_hint') or '').strip()
    hint_phone   = _crm_clean_phone(result.get('phone_hint') or '')
    hint_email   = (result.get('email_hint') or '').strip().lower()
    hint_snippet = (result.get('snippet') or '').strip()

    # Emails found in search snippet are highest-confidence — no fetch needed
    all_emails:  List[str] = []
    email_source = "unknown"
    all_phones:  List[str] = []
    all_html_pages: List[Tuple[str, str]] = []

    if hint_email:
        all_emails.append(hint_email)
        email_source = "snippet"
    if hint_phone:
        all_phones.append(hint_phone)

    # Extract Google rating from search snippet immediately
    rating_data = _crm_extract_google_rating(hint_snippet)

    # Fetch homepage + contact pages in parallel
    page_results = _crm_fetch_contact_pages(domain, timeout=10)
    all_html_pages = page_results

    if not page_results:
        candidate = _crm_fallback_candidate_from_result(result, niche, location, query)
        if candidate:
            if hint_name and not candidate.get('name'):
                candidate['name'] = hint_name
            if hint_company:
                candidate['company'] = hint_company
            if hint_phone and not candidate.get('phone'):
                candidate['phone'] = hint_phone
            if hint_email and not candidate.get('email'):
                candidate['email'] = hint_email
                candidate['email_source'] = email_source
            candidate.update(rating_data)
            candidate['score'] = max(candidate.get('score') or 0, _crm_score_candidate(candidate, niche, location))
        return candidate

    signals_agg: Dict[str, Any] = {
        "niche_hit": False, "location_hit": False, "name": "", "company": "", "facebook": ""
    }
    combined_html = ""
    for html, final_url in page_results:
        combined_html += html
        signals = _crm_parse_page_signals(html, final_url, niche, location)
        _, page_mailto = _crm_find_contact_links(html, final_url)
        for e in page_mailto:
            if e not in all_emails:
                all_emails.insert(0, e)
                email_source = "mailto"
        for e in (signals.get("emails") or []):
            if e not in all_emails:
                all_emails.append(e)
                if email_source == "unknown":
                    email_source = "page_text"
        for p in (signals.get("phones") or []):
            if p not in all_phones:
                all_phones.append(p)
        if not signals_agg["name"] and signals.get("name"):
            signals_agg["name"] = signals["name"]
        if not signals_agg["company"] and signals.get("company"):
            signals_agg["company"] = signals["company"]
        signals_agg["niche_hit"]    = signals_agg["niche_hit"] or bool(signals.get("niche_hit"))
        signals_agg["location_hit"] = signals_agg["location_hit"] or bool(signals.get("location_hit"))
        # Extract facebook from page HTML
        if not signals_agg["facebook"]:
            signals_agg["facebook"] = _crm_find_facebook("", domain, html)
        # Extract Google rating from page text if not already found
        if not rating_data:
            page_text = signals.get("visible_text") or ""
            rating_data = _crm_extract_google_rating(page_text)

    name    = signals_agg.get("name") or hint_name or ""
    company = signals_agg.get("company") or hint_company or _crm_guess_company(result.get("title") or "", domain)
    title   = "Realtor" if re.search(r"real estate|realtor|broker", niche or "", flags=re.I) else "Contact"

    # Detect business type and activity from combined HTML, then free it immediately
    biz_type = _crm_detect_business_type(combined_html, name, company)
    activity  = _crm_detect_activity(combined_html, hint_snippet)
    del combined_html  # free potentially large string before building candidate dict

    candidate: Dict[str, Any] = {
        "name":         name or company,
        "company":      company,
        "title":        title,
        "domain":       domain,
        "website":      f"https://{domain}",
        "phone":        all_phones[0] if all_phones else "",
        "email":        all_emails[0] if all_emails else "",
        "email_source": email_source if all_emails else "none",
        "linkedin":     "",   # filled below in parallel
        "facebook":     signals_agg.get("facebook") or "",
        "business_type": biz_type,
        "activity":     activity,
        "niche_hit":    bool(signals_agg.get("niche_hit")),
        "location_hit": bool(signals_agg.get("location_hit")),
        "notes":        f"Found via web search for {niche or 'lead'} in {location or 'target area'}.",
        "source_query": query,
    }
    candidate.update(rating_data)
    candidate["score"] = _crm_score_candidate(candidate, niche, location)

    # LinkedIn lookup in background thread — only if we have a name or company
    if name or company:
        try:
            li_url = _crm_find_linkedin(name, company, location)
            if li_url:
                candidate["linkedin"] = li_url
                candidate["score"] = _crm_score_candidate(candidate, niche, location)
        except Exception:
            pass

    candidate["warm_reason"] = _crm_warm_reason(candidate, niche, location)
    candidate["confidence"]  = _crm_contact_confidence(
        candidate.get("email") or "", candidate.get("email_source") or "")
    return candidate


def _crm_items_from_rows(rows: List[Dict[str, Any]], niche: str, location: str) -> List[Dict[str, Any]]:
    items = []
    for row in rows[:200]:
        domain = _crm_extract_domain(row.get("domain") or row.get("company") or "")
        name = (row.get("name") or "").strip()
        company = (row.get("company") or "").strip() or (domain.split(".")[0].replace("-", " ").title() if domain else "")
        title = (row.get("title") or "").strip() or ("Realtor" if re.search(r"real estate|realtor|broker", niche or "", flags=re.I) else "Contact")
        if not name and company:
            name = company
        email_candidates = _crm_email_candidates(name, domain)
        item = {
            "name": name,
            "company": company,
            "title": title,
            "domain": domain,
            "website": f"https://{domain}" if domain else "",
            "phone": "",
            "email": (email_candidates[0].get("email","") if email_candidates else ""),
            "niche_hit": True,
            "location_hit": bool(location),
            "notes": (row.get("notes") or "") + (f"\nSeed row for {niche} in {location}." if niche or location else "\nSeed row."),
            "source_query": "seed rows",
        }
        item["score"] = _crm_score_candidate(item, niche, location)
        items.append(item)
    return items


def _crm_bing_search(query: str, max_results: int = 12) -> List[Dict[str, str]]:
    try:
        from urllib.parse import quote_plus
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"}
        url = "https://www.bing.com/search?q=" + quote_plus(query) + "&count=20"
        r = requests.get(url, headers=headers, timeout=20)
        html = r.text or ""
    except Exception:
        return []
    out, seen = [], set()
    if BeautifulSoup is None or not html:
        return out
    try:
        soup = BeautifulSoup(html, "html.parser")
        for li in soup.select("li.b_algo"):
            a = li.select_one("h2 a") or li.select_one("a")
            if not a:
                continue
            href = (a.get("href") or "").strip()
            title = a.get_text(" ", strip=True)
            snippet_el = (li.select_one(".b_caption p") or li.select_one(".b_snippet")
                          or li.select_one("p") or li.select_one(".b_algoSlug"))
            snippet = snippet_el.get_text(" ", strip=True) if snippet_el else ""
            domain = _crm_extract_domain(urlparse(href).netloc or href)
            if not href.startswith("http") or not domain or _crm_is_blocked_domain(domain) or domain in seen:
                continue
            seen.add(domain)
            row: Dict[str, str] = {"url": href, "title": title, "domain": domain, "snippet": snippet}
            snippet_emails = _crm_extract_emails_from_text(snippet)
            if snippet_emails:
                row["email_hint"] = snippet_emails[0]
            out.append(row)
            if len(out) >= max_results:
                break
    except Exception:
        return out
    return out


def _crm_public_search(query: str, max_results: int = 18, niche: str = "", location: str = "") -> List[Dict[str, str]]:
    merged, seen = [], set()
    search_fns = [lambda q, max_results=max_results: _crm_openai_web_search(q, niche=niche, location=location, max_results=max_results)]
    search_fns.extend([_crm_bing_search, _crm_ddg_search])
    for fn in search_fns:
        try:
            rows = fn(query, max_results=max_results)
        except TypeError:
            try:
                rows = fn(query)
            except Exception:
                rows = []
        except Exception:
            rows = []
        for row in rows:
            dom = row.get("domain") or ""
            if not dom or dom in seen or _crm_is_blocked_domain(dom):
                continue
            seen.add(dom)
            merged.append(row)
            if len(merged) >= max_results:
                return merged
    return merged


def _crm_parse_specific_areas(val: str) -> List[str]:
    raw = re.split(r"[\n,;|]+", val or "")
    out, seen = [], set()
    for x in raw:
        s = re.sub(r"\s+", " ", (x or "").strip())
        if not s:
            continue
        k = s.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(s)
    return out[:30]


def _crm_build_queries_v2(niche: str, location: str, lead_count: int, search_mode: str, specific_areas: Optional[List[str]] = None) -> List[str]:
    niche = (niche or "businesses").strip()
    location = (location or "United States").strip()
    mode = (search_mode or "balanced").strip().lower()
    locations = []
    if specific_areas:
        locations.extend([x for x in specific_areas if x])
    if location:
        locations.append(location)
    loc_key = location.strip().lower()
    if loc_key in _CRM_STATE_CITY_MAP:
        extra = _CRM_STATE_CITY_MAP[loc_key]
        locations.extend(extra[:4] if mode == "precision" else extra[:10] if mode == "balanced" else extra[:16])
    deduped, seen = [], set()
    for loc in locations:
        lk = loc.lower()
        if lk not in seen:
            seen.add(lk); deduped.append(loc)
    locations = deduped or [location]
    realtorish = bool(re.search(r"real estate|realtor|broker", niche, flags=re.I))
    # Standard discovery queries
    templates = [
        '{niche} in {loc}',
        '{loc} {niche}',
        '{niche} {loc} contact email',
        '{loc} {niche} office',
        '{loc} {niche} team',
    ]
    # Email-targeted queries — surfaces pages with emails in search snippets
    email_templates = [
        '{niche} {loc} "@" email contact',
        '{niche} {loc} "email us" OR "contact us" OR "reach us"',
        '{loc} {niche} site:*.com email',
    ]
    if realtorish:
        templates.extend([
            '{loc} realtor',
            '{loc} real estate agent',
            '{loc} real estate broker',
            '{loc} realty group',
        ])
        email_templates.append('{loc} realtor agent email contact "@"')
    queries, seen_q = [], set()
    # Interleave standard and email-targeted queries so email hits come early
    all_templates = []
    for i in range(max(len(templates), len(email_templates))):
        if i < len(templates):
            all_templates.append(templates[i])
        if i < len(email_templates):
            all_templates.append(email_templates[i])
    for loc in locations:
        for tpl in all_templates:
            q = re.sub(r"\s+", " ", tpl.format(niche=niche, loc=loc)).strip()
            key = q.lower()
            if key in seen_q:
                continue
            seen_q.add(key)
            queries.append(q)
    max_q = 6 if mode == "precision" else (12 if mode == "balanced" else 18)
    return queries[:max_q]


def _crm_fallback_candidate_from_result(result: Dict[str, str], niche: str, location: str, query: str) -> Optional[Dict[str, Any]]:
    domain = result.get("domain") or _crm_extract_domain(urlparse(result.get("url") or "").netloc or result.get("url") or "")
    if not domain or _crm_is_blocked_domain(domain):
        return None
    title = (result.get("title") or "").strip()
    snippet = (result.get("snippet") or "").strip()
    company = _crm_guess_company(title, domain)
    name = _crm_best_person_name([title], company=company)
    notes = f"Found from public web search for {niche or 'lead'} in {location or 'target area'}. Source query: {query}. {snippet}".strip()
    candidate = {
        "name": name or company or domain.split('.')[0].title(),
        "company": company or domain.split('.')[0].title(),
        "title": "Realtor" if re.search(r"real estate|realtor|broker", niche or "", flags=re.I) else "Contact",
        "domain": domain,
        "website": result.get("url") or (f"https://{domain}"),
        "phone": "",
        "email": "",
        "email_candidates": _crm_email_candidates(name or company or domain, domain),
        "niche_hit": True,
        "location_hit": bool(location),
        "notes": notes,
        "source_query": query,
    }
    candidate["score"] = max(40, _crm_score_candidate(candidate, niche, location) - 10)
    return candidate


def _crm_make_lead_from_search_row(row: Dict[str, Any], niche: str, location: str, query: str, min_score: int = 40) -> Optional[Dict[str, Any]]:
    if not isinstance(row, dict):
        return None
    domain = _crm_extract_domain(row.get('domain') or urlparse(row.get('url') or '').netloc or row.get('url') or '')
    if not domain or _crm_is_blocked_domain(domain):
        return None
    website = (row.get('url') or '').strip()
    if not website:
        website = 'https://' + domain
    elif not website.startswith('http'):
        website = 'https://' + domain
    company = (row.get('company_hint') or row.get('title') or '').strip()
    if not company:
        company = _crm_guess_company(row.get('title') or '', domain) or domain.split('.')[0].replace('-', ' ').title()
    name = (row.get('name_hint') or '').strip()
    if not name:
        name = _crm_best_person_name([row.get('title') or '', row.get('snippet') or ''], company=company)
    phone = _crm_clean_phone(row.get('phone_hint') or row.get('phone') or '')
    public_email = ((row.get('email_hint') or row.get('email') or '')).strip().lower()
    email_candidates = _crm_merge_email_candidates(([public_email] if public_email else []), name or company, domain)
    title = 'Realtor' if re.search(r'real estate|realtor|broker', niche or '', flags=re.I) else 'Contact'
    notes = (row.get('snippet') or '').strip()
    score = 55
    if row.get('name_hint'):
        score += 8
    if phone:
        score += 12
    if public_email:
        score += 12
    if any(x.get('status') == 'public' for x in email_candidates):
        score += 6
    if location:
        score += 3
    score = max(int(min_score or 40), min(96, score))
    return {
        'name': name or company,
        'company': company,
        'title': title,
        'domain': domain,
        'website': website,
        'phone': phone,
        'email': public_email,
        'email_candidates': email_candidates,
        'score': score,
        'confidence': score,
        'niche_hit': True,
        'location_hit': bool(location),
        'notes': notes or f'Public web lead for {niche or "business"} in {location or "target area"}',
        'source_query': query,
    }


def _crm_discover_public_leads(niche: str, location: str, lead_count: int, search_mode: str, existing_domains: Optional[set] = None, specific_areas: Optional[List[str]] = None, require_contact: str = "any", min_score: int = 40) -> List[Dict[str, Any]]:
    queries = _crm_build_queries_v2(niche, location, lead_count, search_mode, specific_areas=specific_areas)
    seen_domains = set([_crm_extract_domain(x) for x in (existing_domains or set()) if x])
    out: List[Dict[str, Any]] = []
    raw_results: List[Dict[str, Any]] = []
    per_query = 8 if (search_mode or 'balanced').lower() == 'precision' else 12 if (search_mode or 'balanced').lower() == 'balanced' else 16

    def include_item(item: Optional[Dict[str, Any]]) -> bool:
        if not item:
            return False
        dom = (item.get('domain') or '').strip().lower()
        if not dom or dom in seen_domains:
            return False
        has_phone = bool((item.get('phone') or '').strip())
        public_email = bool((item.get('email') or '').strip())
        any_email = public_email or bool(item.get('email_candidates') or [])
        if require_contact == 'phone' and not has_phone:
            return False
        if require_contact == 'email' and not any_email:
            return False
        if require_contact == 'phone_or_email' and not (has_phone or any_email):
            return False
        if (item.get('score') or 0) < int(min_score or 40):
            return False
        seen_domains.add(dom)
        out.append(item)
        return True

    # Pass 1: fast lead creation from search results, prioritizing OpenAI web search hints and official sites.
    for q in queries:
        rows = _crm_public_search(q, max_results=per_query, niche=niche, location=location)
        for row in rows:
            dom = _crm_extract_domain(row.get('domain') or urlparse(row.get('url') or '').netloc or row.get('url') or '')
            if not dom or dom in seen_domains or _crm_is_blocked_domain(dom):
                continue
            row['query'] = q
            raw_results.append(row)
            item = _crm_make_lead_from_search_row(row, niche, location, q, min_score=max(35, int(min_score or 40) - 5))
            include_item(item)
            if len(out) >= lead_count:
                break
        if len(out) >= lead_count:
            break

    # Pass 2: enrich a small subset only, to keep the route fast and avoid server/proxy timeouts.
    # Capped at min(lead_count, 8) items and 2 workers to limit parallel RAM usage.
    if len(out) < lead_count and raw_results:
        enrich_pool = raw_results[:min(lead_count, 8)]
        try:
            with ThreadPoolExecutor(max_workers=2) as ex:
                future_map = {ex.submit(_crm_enrich_result, row, niche, location, row.get('query') or ''): row for row in enrich_pool}
                for fut in as_completed(future_map, timeout=18):
                    row = future_map.get(fut) or {}
                    try:
                        item = fut.result(timeout=0)
                    except Exception:
                        item = _crm_make_lead_from_search_row(row, niche, location, row.get('query') or '', min_score=max(35, int(min_score or 40) - 5))
                    include_item(item)
                    if len(out) >= lead_count:
                        break
        except Exception:
            pass

    # Pass 3: deterministic fallback rows from raw results so the user always gets a usable list.
    fallback_pool = list(raw_results)  # copy ref before clearing
    raw_results.clear()                # free search-result memory before fallback pass
    if len(out) < lead_count:
        for row in fallback_pool:
            item = _crm_fallback_candidate_from_result(row, niche, location, row.get('query') or '') or _crm_make_lead_from_search_row(row, niche, location, row.get('query') or '', min_score=max(35, int(min_score or 40) - 5))
            if include_item(item) and len(out) >= lead_count:
                break

    out.sort(key=lambda x: ((1 if x.get('phone') else 0) + (1 if (x.get('email') or x.get('email_candidates')) else 0), x.get('score') or 0), reverse=True)
    return out[:lead_count]


@app.post("/api/crm/lead_lab")
def api_crm_lead_lab():
    import hashlib as _hl, time as _t2, json as _json
    from flask import stream_with_context, Response as _Resp
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    # Strict per-minute rate limit — each call triggers hundreds of outbound HTTP requests
    _rl_ll = _check_rate_limit("lead_lab", 2)  # max 2 calls per minute per user
    if _rl_ll:
        return _rl_ll
    # Per-plan daily limit
    _uname   = u.get("username", "")
    _plan_k  = _get_user_plan(_uname)
    _ll_ok, _ll_used, _ll_limit = _check_lead_lab_limit(_uname, _plan_k)
    if not _ll_ok:
        _plan_nm = (PLANS.get(_normalize_plan_key(_plan_k)) or {}).get("name", "your plan")
        return jsonify({"ok": False, "error": (
            f"You've used all {_ll_limit} Lead Lab runs included in {_plan_nm} today. "
            f"Resets at midnight UTC — or upgrade for more daily runs."
        )}), 429
    # _increment_ll_usage called inside _generate() after a slot is acquired
    payload = request.get_json(silent=True) or {}
    niche          = (payload.get("niche") or "").strip()
    location       = (payload.get("location") or "").strip()
    specific_areas = _crm_parse_specific_areas(payload.get("specific_areas") or "")
    search_mode    = (payload.get("search_mode") or "balanced").strip().lower()
    require_contact= (payload.get("require_contact") or "phone_or_email").strip().lower()
    biz_type_filter= (payload.get("business_type") or "any").strip().lower()
    require_social = (payload.get("require_social") or "any").strip().lower()
    require_reviews= payload.get("require_reviews") is True or str(payload.get("require_reviews","")).lower() == "true"
    try:
        lead_count = int(payload.get("lead_count") or 25)
    except Exception:
        lead_count = 25
    lead_count = max(1, min(100, lead_count))

    if not niche and not location and not specific_areas:
        return jsonify({"ok": False, "error": "Add a niche, location, or specific areas to search"}), 400

    def _generate():
        import time as _ti
        _slot  = False
        _entry = {"u": _uname}
        with _LL_STATE_LOCK:
            _LL_STATE["queue"].append(_entry)
        try:
            # ── Queue: wait for a free concurrency slot ───────────────────────
            _wait_start = _ti.monotonic()
            while True:
                with _LL_STATE_LOCK:
                    try:
                        _qpos = _LL_STATE["queue"].index(_entry) + 1
                    except ValueError:
                        _qpos = 1
                    if _LL_STATE["active"] < _LL_MAX_CONCURRENT:
                        _LL_STATE["active"] += 1
                        try:
                            _LL_STATE["queue"].remove(_entry)
                        except ValueError:
                            pass
                        _slot = True
                        break
                if _ti.monotonic() - _wait_start > 300:
                    yield _json.dumps({"ok": False, "error": "No Lead Lab slot opened in 5 minutes — please try again."}) + "\n"
                    return
                if _qpos == 1:
                    _qmsg = "You’re next — another search is finishing up, starting yours shortly."
                else:
                    _qmsg = (f"Queue #{_qpos} — Lead Lab searches hundreds of sites at once so we cap "
                             f"concurrent runs. {_qpos - 1} search{'es' if _qpos > 2 else ''} running "
                             f"ahead of you — won’t be long.")
                yield _json.dumps({"queued": True, "position": _qpos, "msg": _qmsg}) + "\n"
                _ti.sleep(4)
            # Slot acquired — charge the daily run count, then do the work
            _increment_ll_usage(_uname)
            # Check cache first
            _cache_str = f"{niche}|{location}|{search_mode}|{require_contact}|{biz_type_filter}|{require_social}|{require_reviews}|{specific_areas}"
            _cache_key = _hl.md5(_cache_str.encode()).hexdigest()
            _LEAD_LAB_CACHE = getattr(api_crm_lead_lab, "_cache", None)
            if _LEAD_LAB_CACHE is None:
                api_crm_lead_lab._cache = {}
            _cached_entry = api_crm_lead_lab._cache.get(_cache_key)
            if _cached_entry and (_ti.monotonic() - _cached_entry["ts"]) < 7200:
                _cached_final = _cached_entry["results"][:lead_count]
                yield _json.dumps({"ok": True, "items": _cached_final, "count": len(_cached_final), "warning": "", "cached": True}) + "\n"
                return

            # Heartbeat loop — send whitespace every 5 s to prevent Render 30 s proxy timeout
            import threading as _thr
            _done = [False]
            _result = [None]
            _error = [None]

            def _worker():
              with app.app_context():
                try:
                    discovered = _crm_discover_public_leads(
                        niche, location, min(lead_count * 2, 60), search_mode,
                        existing_domains=set(),
                        specific_areas=specific_areas,
                        require_contact=require_contact,
                        min_score=1
                    )
                    final: list = []
                    seen: set = set()
                    for item in discovered:
                        dom = (item.get("domain") or "").strip().lower()
                        key = dom or ((item.get("website") or item.get("company") or item.get("name") or "").strip().lower())
                        if not key or key in seen:
                            continue
                        if biz_type_filter != "any" and item.get("business_type") and item["business_type"] != biz_type_filter:
                            continue
                        if require_social == "linkedin" and not item.get("linkedin"):
                            continue
                        if require_social == "any_social" and not (item.get("linkedin") or item.get("facebook")):
                            continue
                        if require_reviews and not item.get("google_rating"):
                            continue
                        seen.add(key)
                        if not item.get("warm_reason"):
                            item["warm_reason"] = _crm_warm_reason(item, niche, location)
                        if not item.get("confidence"):
                            item["confidence"] = _crm_contact_confidence(item.get("email") or "", item.get("email_source") or "")
                        final.append(item)
                        if len(final) >= lead_count:
                            break
                    _result[0] = final
                except Exception as ex:
                    _error[0] = str(ex)
                finally:
                    _done[0] = True

            t = _thr.Thread(target=_worker, daemon=True)
            t.start()
            _deadline = _ti.monotonic() + 55  # hard cap — stay under Render's 60 s proxy timeout
            while not _done[0]:
                # Yield a padded heartbeat large enough to force Gunicorn/Nginx buffer flush
                yield (": heartbeat\n\n" + " " * 512 + "\n")
                _ti.sleep(4)
                if _ti.monotonic() > _deadline:
                    _done[0] = True  # signal worker to stop (best-effort)
                    break
            t.join(timeout=3)

            if _error[0]:
                yield _json.dumps({"ok": False, "error": f"Lead Lab server error: {_error[0]}"}) + "\n"
                return

            final = _result[0] or []
            warning = ""
            if not final:
                warning = "No leads matched your filters. Try loosening the business type or social filters."
            elif len(final) < lead_count:
                warning = f"Found {len(final)} leads matching your filters."

            try:
                _uname = (u.get("username") if isinstance(u, dict) else None) or ""
                if _uname:
                    _pts = 10 + (2 * min(len(final), lead_count))
                    _award_points(_uname, f"Ran Lead Lab ({min(len(final),lead_count)} leads)", _pts)
            except Exception:
                pass

            try:
                api_crm_lead_lab._cache[_cache_key] = {"results": final, "ts": _ti.monotonic()}
                if len(api_crm_lead_lab._cache) > 50:
                    oldest = min(api_crm_lead_lab._cache.items(), key=lambda x: x[1]["ts"])
                    api_crm_lead_lab._cache.pop(oldest[0], None)
            except Exception:
                pass

            payload = _json.dumps({"ok": True, "items": final[:lead_count], "count": min(len(final), lead_count), "warning": warning})
            del final  # free lead list before yielding so GC can reclaim it
            import gc as _gc; _gc.collect()
            yield payload + "\n"
        except Exception as e:
            try:
                append_log("crm_lead_lab_error", {"error": str(e), "at": now_iso()})
            except Exception:
                pass
            yield _json.dumps({"ok": False, "error": f"Lead Lab server error: {str(e)}"}) + "\n"
        finally:
            # Always release the slot so the next queued user can proceed
            with _LL_STATE_LOCK:
                if _slot:
                    _LL_STATE["active"] = max(0, _LL_STATE["active"] - 1)
                try:
                    _LL_STATE["queue"].remove(_entry)
                except ValueError:
                    pass

    return _Resp(stream_with_context(_generate()), content_type="text/plain; charset=utf-8",
                 headers={"Cache-Control": "no-store", "X-Accel-Buffering": "no"})


