@app.post("/api/tts")
def api_tts():
    """Convert text to speech using OpenAI TTS-1.
    Returns raw MP3 bytes so the frontend can play them with an Audio element."""
    from flask import Response

    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    payload = request.get_json(force=True) or {}
    _raw_text = (payload.get("text") or "").strip()
    # Strip markdown so TTS doesn't speak "asterisk asterisk bold text asterisk asterisk"
    import re as _re
    _raw_text = _re.sub(r'\*{1,3}(.*?)\*{1,3}', r'\1', _raw_text)      # bold/italic
    _raw_text = _re.sub(r'#{1,6}\s+', '', _raw_text)                     # headings
    _raw_text = _re.sub(r'`{1,3}[^`]*`{1,3}', '', _raw_text)            # code
    _raw_text = _re.sub(r'\[([^\]]+)\]\([^)]+\)', r'\1', _raw_text)     # links
    _raw_text = _re.sub(r'^\s*[-*+]\s+', '', _raw_text, flags=_re.MULTILINE)  # bullets
    _raw_text = _re.sub(r'^\s*\d+\.\s+', '', _raw_text, flags=_re.MULTILINE)  # numbered
    text  = _raw_text.strip()[:2000]   # cap at ~30 s
    voice = (payload.get("voice") or "alloy").strip()
    if voice not in ("alloy", "echo", "fable", "onyx", "nova", "shimmer"):
        voice = "alloy"
    if not text:
        return jsonify({"ok": False, "error": "Missing text"}), 400

    # TTS: prefer the user's own stored key, fall back to the server-level OPENAI_API_KEY env var.
    # This means voice works as long as EITHER the user has entered their key OR the server has one.
    user_key = _decrypt_field(((u.get("settings") or {}).get("openai_key") or "").strip())
    openai_key = user_key or (OPENAI_API_KEY or "").strip()
    username = u.get("username", "unknown")
    key_source = "user_settings" if user_key else ("env_var" if openai_key else "none")
    print(f"[TTS] user={username} key_source={key_source} key_len={len(openai_key)} text_len={len(text)} voice={voice}", flush=True)
    if not openai_key:
        print(f"[TTS] FAIL: no openai_key anywhere for user={username}", flush=True)
        return jsonify({"ok": False, "error": "Voice requires an OpenAI API key. Go to Settings and paste your OpenAI key (sk-...)."}), 400

    openai_key = openai_key.strip()

    try:
        oai = OpenAI(api_key=openai_key)
        print(f"[TTS] streaming tts-1 voice={voice} chars={len(text)}", flush=True)
        def _tts_stream():
            with oai.audio.speech.with_streaming_response.create(
                model="tts-1", voice=voice, input=text
            ) as stream:
                for chunk in stream.iter_bytes(chunk_size=4096):
                    yield chunk
        return Response(
            _tts_stream(),
            mimetype="audio/mpeg",
            headers={
                "Cache-Control":        "no-store",
                "X-Accel-Buffering":    "no",
                "Content-Disposition":  "inline; filename=speech.mp3",
            },
        )
    except Exception as exc:
        print(f"[TTS] EXCEPTION: {exc}", flush=True)
        code, msg = _classify_openai_error(exc)
        return jsonify({"ok": False, "error": msg}), code


@app.post("/api/transcribe/chunk")
def api_transcribe_chunk():
    """Receive one chunk of a chunked video upload. Saves to temp dir keyed by upload_id."""
    import tempfile as _tc, json as _jc
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    upload_id   = (request.form.get("upload_id") or "").strip()
    chunk_index = int(request.form.get("chunk_index") or 0)
    total_chunks= int(request.form.get("total_chunks") or 1)
    filename    = (request.form.get("filename") or "upload").strip()
    chunk_file  = request.files.get("chunk")
    if not upload_id or not chunk_file:
        return jsonify({"ok": False, "error": "Missing upload_id or chunk"}), 400
    # Sanitize upload_id to safe chars only
    import re as _re
    if not _re.match(r'^vt_[0-9]+_[a-z0-9]{4,12}$', upload_id):
        return jsonify({"ok": False, "error": "Invalid upload_id"}), 400
    chunk_dir = Path(_tc.gettempdir()) / f"sa_vtchunk_{upload_id}"
    chunk_dir.mkdir(parents=True, exist_ok=True)
    chunk_path = chunk_dir / f"chunk_{chunk_index:06d}"
    chunk_file.save(str(chunk_path))
    # Store metadata for assembly step
    meta = {"total_chunks": total_chunks, "filename": filename}
    (chunk_dir / "meta.json").write_text(_jc.dumps(meta))
    return jsonify({"ok": True, "chunk": chunk_index})


@app.post("/api/transcribe")
def api_transcribe():
    """Transcribe via OpenAI Whisper-1. Accepts either:
    - FormData with 'file' field (direct upload, legacy / small files)
    - JSON body with 'upload_id' + 'filename' (chunked upload — assembles chunks first)
    Streams heartbeat lines to survive proxy timeouts, then sends final JSON line."""
    try:
        return _api_transcribe_inner()
    except Exception as exc:
        import traceback as _tb
        print(f"[TRANSCRIBE] UNHANDLED EXCEPTION: {exc}\n{_tb.format_exc()}", flush=True)
        return jsonify({"ok": False, "error": f"Transcription error: {str(exc)}"}), 500

def _api_transcribe_inner():
    from flask import Response
    import io, threading, queue as _tq, json as _tj, tempfile as _tmpfile, shutil as _shutil, subprocess as _sp, os as _os

    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    username   = u.get("username", "unknown")
    user_key   = _decrypt_field(((u.get("settings") or {}).get("openai_key") or "").strip())
    openai_key = user_key or (OPENAI_API_KEY or "").strip()
    if not openai_key:
        return jsonify({"ok": False, "error": "Transcription requires an OpenAI API key. Add yours in Settings → API Keys."}), 400

    tmp_dir  = _tmpfile.mkdtemp(prefix="sa_transcribe_")
    orig_path = None

    content_type = (request.content_type or "").lower()
    if "application/json" in content_type:
        # ── Chunked upload path: assemble saved chunks ────────────────────────
        body = request.get_json(silent=True) or {}
        upload_id = (body.get("upload_id") or "").strip()
        filename  = (body.get("filename") or "upload").strip()
        if not upload_id:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": "Missing upload_id"}), 400
        chunk_dir = Path(_tmpfile.gettempdir()) / f"sa_vtchunk_{upload_id}"
        if not chunk_dir.exists():
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": "Upload session not found — please re-upload the file."}), 400
        try:
            meta = _tj.loads((chunk_dir / "meta.json").read_text())
            total_chunks = int(meta.get("total_chunks", 0))
        except Exception:
            total_chunks = 0
        # Gather chunk files in order
        chunk_files = sorted(chunk_dir.glob("chunk_*"))
        if len(chunk_files) != total_chunks or total_chunks == 0:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": f"Upload incomplete ({len(chunk_files)}/{total_chunks} chunks). Please try again."}), 400
        ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else "mp4"
        allowed = {"mp4", "mov", "webm", "mp3", "m4a", "wav"}
        if ext not in allowed:
            ext = "mp4"
        orig_path = _os.path.join(tmp_dir, f"upload.{ext}")
        try:
            with open(orig_path, "wb") as out_f:
                for cf in chunk_files:
                    out_f.write(cf.read_bytes())
        except Exception as ae:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": f"Assembly failed: {ae}"}), 500
        finally:
            _shutil.rmtree(str(chunk_dir), ignore_errors=True)
    else:
        # ── Direct upload path (legacy / small files) ─────────────────────────
        if "file" not in request.files:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": "No file uploaded"}), 400
        f        = request.files["file"]
        filename = f.filename or "upload"
        ext      = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
        allowed  = {"mp4", "mov", "webm", "mp3", "m4a", "wav"}
        if ext not in allowed:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": f"Unsupported file type '.{ext}'. Use MP4, MOV, WEBM, MP3, M4A, or WAV."}), 400
        orig_path = _os.path.join(tmp_dir, f"upload.{ext}")
        try:
            f.save(orig_path)
        except Exception as save_err:
            _shutil.rmtree(tmp_dir, ignore_errors=True)
            return jsonify({"ok": False, "error": f"Upload failed: {save_err}"}), 500

    file_size = _os.path.getsize(orig_path)
    print(f"[TRANSCRIBE] user={username} file={filename} size={file_size} ext={ext}", flush=True)

    WHISPER_MAX = 24 * 1024 * 1024   # Whisper API hard limit is 25 MB; stay under

    result_q: _tq.Queue = _tq.Queue()

    def _do_transcribe():
        try:
            audio_path = orig_path

            # ── Compress with ffmpeg if file exceeds Whisper's limit ──────────
            if _os.path.getsize(audio_path) > WHISPER_MAX:
                compressed = _os.path.join(tmp_dir, "audio.mp3")
                try:
                    proc = _sp.run(
                        ["ffmpeg", "-y", "-i", audio_path,
                         "-vn",          # drop video stream
                         "-ac", "1",     # mono
                         "-ar", "16000", # 16 kHz sample rate
                         "-b:a", "32k",  # 32 kbps — good enough for speech
                         compressed],
                        capture_output=True, timeout=300
                    )
                    if proc.returncode == 0 and _os.path.getsize(compressed) > 0:
                        audio_path = compressed
                        print(f"[TRANSCRIBE] compressed to {_os.path.getsize(audio_path)} bytes", flush=True)
                    else:
                        print(f"[TRANSCRIBE] ffmpeg failed (rc={proc.returncode}): {proc.stderr.decode(errors='replace')[:300]}", flush=True)
                except Exception as fe:
                    print(f"[TRANSCRIBE] ffmpeg error: {fe}", flush=True)

            oai = OpenAI(api_key=openai_key.strip())
            audio_size = _os.path.getsize(audio_path)

            # ── If still over limit, chunk and stitch ─────────────────────────
            if audio_size > WHISPER_MAX:
                chunk_size  = WHISPER_MAX - 512 * 1024   # 512 KB safety margin
                parts       = []
                chunk_ext   = audio_path.rsplit(".", 1)[-1] if "." in audio_path else "mp3"
                with open(audio_path, "rb") as af:
                    idx = 0
                    while True:
                        chunk_bytes = af.read(chunk_size)
                        if not chunk_bytes:
                            break
                        buf = io.BytesIO(chunk_bytes)
                        buf.name = f"chunk_{idx}.{chunk_ext}"
                        part = oai.audio.transcriptions.create(model="whisper-1", file=buf)
                        parts.append((part.text or "").strip())
                        idx += 1
                transcript = " ".join(parts)
            else:
                # ── Normal single-shot transcription ─────────────────────────
                with open(audio_path, "rb") as af:
                    buf = io.BytesIO(af.read())
                buf.name = _os.path.basename(audio_path)
                result = oai.audio.transcriptions.create(model="whisper-1", file=buf)
                transcript = (result.text or "").strip()

            print(f"[TRANSCRIBE] done user={username} chars={len(transcript)}", flush=True)
            result_q.put({"ok": True, "transcript": transcript})

        except Exception as exc:
            print(f"[TRANSCRIBE] EXCEPTION: {exc}", flush=True)
            try:
                _, msg = _classify_openai_error(exc)
            except Exception:
                msg = str(exc) or "Transcription failed — please try again."
            result_q.put({"ok": False, "error": msg})
        finally:
            _shutil.rmtree(tmp_dir, ignore_errors=True)

    threading.Thread(target=_do_transcribe, daemon=True).start()

    def _stream():
        import time as _t
        deadline = _t.time() + 300   # 5-minute timeout for large files
        while _t.time() < deadline:
            try:
                res = result_q.get(timeout=5)
                yield _tj.dumps(res) + "\n"
                return
            except _tq.Empty:
                yield " \n"   # heartbeat — keeps Render proxy alive
        yield _tj.dumps({"ok": False, "error": "Transcription timed out — try a shorter clip."}) + "\n"

    return Response(
        _stream(),
        mimetype="text/plain",
        headers={"X-Accel-Buffering": "no", "Cache-Control": "no-cache"},
    )


