@app.get("/extension/download")
def extension_download():
    u = current_user()
    if not u: return redirect(url_for("login") + "?next=/extension/download")
    try:
        uname = (u.get("username") if isinstance(u, dict) else None) or _get_session_username()
        api_key = _ext_api_key_for_user(uname)
        base_url = (PUBLIC_BASE_URL or "").rstrip("/")
        if not base_url:
            base_url = request.url_root.rstrip("/")
            if base_url.startswith("http://"):
                base_url = "https://" + base_url[7:]
        import json as _json

        def _fix(s):
            try:
                s.encode("utf-8")
                return s
            except UnicodeEncodeError:
                return s.encode("utf-16", "surrogatepass").decode("utf-16")

        # Personalised manifest — add server to host_permissions
        manifest_obj = _json.loads(_fix(_EXT_MANIFEST))
        manifest_obj["host_permissions"].append(base_url + "/*")
        personalised_manifest = _json.dumps(manifest_obj, indent=2)

        # popup.js — prepend preset credentials so it auto-connects on install
        preset_lines = "\n".join([
            "var SA_PRESET_URL = " + _json.dumps(base_url) + ";",
            "var SA_PRESET_KEY = " + _json.dumps(api_key) + ";",
            "var SA_PRESET_USER = " + _json.dumps(uname) + ";",
            "",
        ])
        personalised_popup = preset_lines + _fix(_EXT_POPUP_JS)

        # background.js — hardcode credentials so extension works on first load
        bg_preset = "\n".join([
            "// Auto-configured for " + uname,
            "var SA_URL  = " + _json.dumps(base_url) + ";",
            "var SA_KEY  = " + _json.dumps(api_key) + ";",
            "var SA_USER = " + _json.dumps(uname) + ";",
            "chrome.storage.local.set({ sa_url: SA_URL, sa_key: SA_KEY, sa_user: SA_USER });",
            "",
        ])
        personalised_bg = bg_preset + _fix(_EXT_BACKGROUND)

        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", _zipfile.ZIP_DEFLATED) as zf:
            zf.writestr("manifest.json",  personalised_manifest)
            zf.writestr("background.js",  personalised_bg)
            zf.writestr("content.css",    _fix(_EXT_CONTENT_CSS))
            zf.writestr("content.js",     _fix(_EXT_CONTENT_JS))
            zf.writestr("popup.html",     _fix(_EXT_POPUP_HTML))
            zf.writestr("popup.js",       personalised_popup)
        buf.seek(0)
        resp = make_response(buf.read())
        resp.headers["Content-Type"]        = "application/zip"
        resp.headers["Content-Disposition"] = 'attachment; filename="simply-agentic-extension-v2.zip"'
        resp.headers["Cache-Control"]       = "no-store"
        return resp
    except Exception as e:
        _capture_error(e, context="extension_download")
        return jsonify({"ok": False, "error": str(e)}), 500

@app.get("/api/extension/auth")
def api_extension_auth():
    uname = _ext_authenticate(request)
    if not uname:
        resp = jsonify({"ok": False, "error": "Invalid or missing extension key"})
        resp.status_code = 401
    else:
        resp = jsonify({"ok": True, "username": uname, "app": APP_TITLE})
    resp.headers["Access-Control-Allow-Origin"]  = "*"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type, X-SA-Extension-Key"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
    return resp


