@app.post("/api/extension/import_lead")
def api_extension_import_lead():
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    p    = request.get_json(silent=True) or {}
    name = (p.get("name") or "").strip()
    if not name:
        name = "Facebook Contact"  # never hard-fail — use fallback name
    crm       = _crm_load(uname)
    plan_key  = _get_user_plan(uname)
    plan_info = PLANS.get(_normalize_plan_key(plan_key)) or PLANS["solo"]
    max_c     = plan_info.get("crm_contacts")
    if max_c is not None and len(crm.get("clients") or {}) >= max_c:
        return jsonify({"ok": False, "error": f"Contact limit reached ({max_c}). <a href='/stripe/manage' style='color:#c4b5fd;'>Upgrade your plan →</a>"}), 403
    cid  = _crm_new_id("c")
    now  = now_iso()
    tags = p.get("tags") or ["Facebook"]
    if isinstance(tags, str):
        tags = [t.strip() for t in tags.split(",") if t.strip()]
    # Merge any custom_fields passed by the extension (photo, last_post, etc.)
    ext_cf = p.get("custom_fields") or {}
    if not isinstance(ext_cf, dict): ext_cf = {}
    client_cf = {
        "facebook_url":  (p.get("profile_url") or "").strip(),
        "import_source": (p.get("source")      or "facebook_extension"),
    }
    # Pull profile photo + activity data if extension sent them
    for _cf_key in ("profile_photo_url", "last_post_date", "activity_tag"):
        if ext_cf.get(_cf_key): client_cf[_cf_key] = ext_cf[_cf_key]
    client = {
        "id": cid, "name": name,
        "company": (p.get("company") or "").strip(),
        "email":   (p.get("email")   or "").strip(),
        "phone":   (p.get("phone")   or "").strip(),
        "tags":    tags, "status": "lead", "pipeline_stage": (p.get("pipeline_stage") or "Lead").strip(),
        "notes":   (p.get("notes")   or "").strip(),
        "custom_fields": client_cf,
        "created_at": now, "updated_at": now,
    }
    try:    client = _crm_enrich_client_record(client)
    except Exception as _enrich_err: _capture_error(_enrich_err, context="extension_import_lead_enrich")
    crm["clients"][cid] = client
    _crm_save(uname, crm)
    _award_points(uname, "Imported a Facebook lead via extension", 5)
    _fire_outbound_webhooks(uname, "new_lead", {
        "contact": name, "source": p.get("source","facebook_extension"),
        "facebook_url": p.get("profile_url","")
    })
    return jsonify({"ok": True, "client_id": cid, "name": name})


@app.post("/api/extension/draft_message")
def api_extension_draft_message():
    uname = _ext_authenticate(request)
    if not uname:
        resp = jsonify({"ok": False, "error": "Not authenticated"})
        resp.headers["Access-Control-Allow-Origin"] = "*"
        return resp, 401

    # Server-side daily message cap
    today = datetime.utcnow().strftime("%Y-%m-%d")
    _ud = load_users()
    _urec = (_ud.get("users") or {}).get(uname, {})
    daily_msgs = (_urec.get("settings") or {}).get("ext_daily_msgs", {})
    count_today = daily_msgs.get(today, 0)
    DAILY_MSG_CAP_SRV = 20
    if count_today >= DAILY_MSG_CAP_SRV:
        resp = jsonify({"ok": False, "error": "Daily message limit (" + str(DAILY_MSG_CAP_SRV) + "/day) reached. Resets midnight UTC."})
        resp.headers["Access-Control-Allow-Origin"] = "*"
        return resp, 429

    p                = request.get_json(silent=True) or {}
    name             = (p.get("name")    or "").strip()
    if not name or name.lower() in ("this page", "unknown", "there", "messenger contact", "messenger"):
        name = "someone"
    context          = (p.get("context") or "").strip()
    channel          = (p.get("channel") or "messenger").strip()
    keywords_matched = p.get("keywords") or []
    op               = _load_operator_profile(uname)
    op_name          = (op.get("display_name") or "Operator").strip()
    business         = (op.get("business")     or "").strip()
    offers           = (op.get("offers")       or "").strip()
    first            = name.split()[0] if name and name not in ("someone", "there") else "there"

    sniffer_note = ""
    if keywords_matched:
        kw_str       = ", ".join(str(k) for k in keywords_matched[:5])
        ctx_snippet  = context[:200] if context else "something relevant"
        sniffer_note = (
            " IMPORTANT: This person posted about: " + ctx_snippet + ". "
            "Their post matched keywords: " + kw_str + ". "
            "Reference their interest naturally — don't make it feel like surveillance. "
            "Sound like a human who genuinely relates to what they shared."
        )

    requested_teammate = (p.get("teammate") or "Sunshine").strip()
    # Validate teammate name against known teammates
    valid_teammates = ["Sunshine", "Alex", "Willow", "Ava", "Orion", "Luna", "Atlis"]
    draft_teammate = requested_teammate if requested_teammate in valid_teammates else "Sunshine"

    prompt = (
        "Write a short warm personal outreach message to " + name
        + " on Facebook " + channel.title() + ". "
        + "From: " + op_name + ((" at " + business) if business else "") + ". "
        + (("We offer: " + offers + ". ") if offers else "")
        + "Under 100 words. No subject line. Sound human not salesy. "
        + "Start with their first name (" + first + "). Do NOT mention AI."
        + sniffer_note
        + ((" Context: " + context[:200]) if context and not keywords_matched else "")
    )
    try:
        draft = _call_teammate_prompt_for_user(uname, draft_teammate, prompt)
        if not draft: raise ValueError("Empty response")
        # Increment server-side daily counter
        daily_msgs[today] = count_today + 1
        _urec.setdefault("settings", {})["ext_daily_msgs"] = daily_msgs
        (_ud.setdefault("users", {}))[uname] = _urec
        save_users(_ud)
        _award_points(uname, "Drafted extension message", 3)
        resp = jsonify({"ok": True, "draft": draft.strip()})
        resp.headers["Access-Control-Allow-Origin"] = "*"
        return resp
    except Exception as e:
        _capture_error(e, context="extension_draft_message")
        # Fallback: return a template message so the user always has something to send
        fallback = (
            f"Hey {first}! Came across your profile and loved what you're doing. "
            f"I'd love to connect and see if there's a way we can support each other. "
            f"Would you be open to a quick chat?"
        )
        resp = jsonify({"ok": True, "draft": fallback, "fallback": True})
        resp.headers["Access-Control-Allow-Origin"] = "*"
        return resp



# ── Extension v2 routes: keyword sniffer + rate limits ───────────────────────

@app.get("/api/extension/get_keywords")
def api_extension_get_keywords():
    """Return the user's saved lead sniffer keywords."""
    uname = _ext_authenticate(request)
    if not uname:
        resp = jsonify({"ok": False, "error": "Not authenticated"})
        resp.headers["Access-Control-Allow-Origin"] = "*"
        return resp, 401
    users_data = load_users()
    urec = (users_data.get("users") or {}).get(uname, {})
    keywords = (urec.get("settings") or {}).get("sniffer_keywords", [])
    resp = jsonify({"ok": True, "keywords": keywords})
