@app.get("/api/extension/check_contact")
def api_extension_check_contact():
    """Check if a Facebook profile URL already exists as a CRM contact."""
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    url = (request.args.get("url") or "").strip().rstrip("/").lower()
    if not url:
        return jsonify({"ok": False, "error": "url param required"}), 400
    crm = _crm_load(uname)
    for cid, c in (crm.get("clients") or {}).items():
        stored = (c.get("custom_fields") or {}).get("facebook_url", "").strip().rstrip("/").lower()
