@app.post("/api/social/connect/token")
def api_sp_connect_token():
    """Accept a pasted Page Access Token for Facebook/Instagram — no OAuth needed."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    body = request.get_json(silent=True) or {}
    platform = (body.get("platform") or "").lower().strip()
    access_token = (body.get("access_token") or "").strip()
    page_id = (body.get("page_id") or "").strip()
    page_name = (body.get("page_name") or page_id).strip()
    if platform not in ("facebook", "instagram"):
        return jsonify({"ok": False, "error": "Platform must be facebook or instagram"}), 400
    if not access_token:
        return jsonify({"ok": False, "error": "access_token required"}), 400
    if not page_id:
        return jsonify({"ok": False, "error": "page_id required"}), 400

    # Quick validation: hit Graph API to confirm token is valid
    import urllib.request as _urlreq, urllib.error as _urlerr
    _verified = False
    try:
        _url = f"https://graph.facebook.com/v19.0/me?fields=id,name&access_token={access_token}"
        with _urlreq.urlopen(_url, timeout=8) as _resp:
            _data = json.loads(_resp.read())
        if "error" in _data:
            return jsonify({"ok": False, "error": "Invalid token: " + _data["error"].get("message", "unknown error")})
        _verified = True
    except _urlerr.HTTPError as _e:
        try:
            _body = json.loads(_e.read())
            _msg = _body.get("error", {}).get("message", str(_e))
        except Exception:
            _msg = str(_e)
        return jsonify({"ok": False, "error": "Token validation failed: " + _msg})
    except Exception as _e:
        # Network error — save anyway (token may still work) but mark it
        # unverified and tell the user rather than implying it's confirmed.
        _verified = False

    conns = _load_sp_conns(uname)
    conns[platform] = {
        "access_token": access_token,
        "page_id": page_id,
        "page_name": page_name,
        "token_type": "page",
        "verified": _verified,
    }
    _save_sp_conns(uname, conns)
    return jsonify({"ok": True, "page_name": page_name, "verified": _verified,
                    "warning": None if _verified else "Saved, but we couldn't verify the token (network issue). If posting fails, re-paste it."})


@app.post("/api/social/draft_ai")
def api_sp_draft_ai():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    body = request.get_json(silent=True) or {}
    topic = (body.get("topic") or "").strip()
    if not topic:
        return jsonify({"ok": False, "error": "Topic required"}), 400
    platforms = body.get("platforms") or ["facebook"]
    tone = (body.get("tone") or "engaging").strip()
    teammate = (body.get("teammate") or "Luna").strip()
    reg = load_registry(uname)
    installed = (reg.get("installed") or {})
    t_defn = installed.get(teammate) or PREBUILT_LOCKED.get(teammate) or {}
    system = teammate_system_prompt(t_defn) if t_defn else f"You are {teammate}, a social media content specialist."
    platform_str = " and ".join(p.title() for p in platforms)
    # Inject operator brand context so the post sounds like their brand
    op = _load_operator_profile(uname) or {}
    brand_ctx = ""
    if op.get("business") or op.get("audience") or op.get("offers"):
        brand_ctx = (
            "\nBRAND CONTEXT (apply to the post):\n"
            + (f"Business: {op['business']}\n" if op.get("business") else "")
            + (f"Target audience: {op['audience']}\n" if op.get("audience") else "")
            + (f"Offers/services: {op['offers']}\n" if op.get("offers") else "")
            + (f"Brand voice/notes: {op['notes']}\n" if op.get("notes") else "")
        )
    prompt = (
        f"Write a {tone} social media post for {platform_str} about: {topic}.\n"
        "Include relevant hashtags at the end. Keep it concise, authentic, and engaging. "
        "Return ONLY the post text — no preamble, no explanation."
        + brand_ctx
    )
    try:
        draft = call_llm(system, [{"role": "user", "content": prompt}], temperature=0.75)
        return jsonify({"ok": True, "draft": draft.strip()})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

